// Package cli implements the messgo command-line interface, mirroring PHPMD's
// argument layout: `messgo <paths> <format> <ruleset[,...]> [options]`.
package cli

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/quality-gates/messgo/internal/report"
	"github.com/quality-gates/messgo/internal/rule"
	"github.com/quality-gates/messgo/internal/ruleset"
	"github.com/quality-gates/messgo/internal/runner"
	"github.com/quality-gates/messgo/internal/version"
)

// Exit codes match PHPMD.
const (
	ExitSuccess         = 0
	ExitError           = 1
	ExitViolation       = 2
	ExitProcessingError = 3
)

type options struct {
	paths            string
	format           string
	rulesets         string
	minPriority      int
	maxPriority      int
	reportFile       string
	suffixes         string
	exclude          string
	ruleFilter       ruleFilter
	strict           bool
	color            bool
	verbose          bool
	ignoreErrors     bool
	ignoreViolations bool
	ignoreTests      bool
}

// ruleFilter selects a subset of rules by name: --enable/--only (whitelist)
// and --disable (blacklist), each a comma-separated list.
type ruleFilter struct {
	enable  string
	disable string
}

// Main runs the CLI and returns a process exit code.
func Main(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		printUsage(stderr)
		return ExitError
	}
	if code, handled := handleInfoFlags(args, stdout); handled {
		return code
	}

	opt, positionals, err := parseArgs(args)
	if err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	if len(positionals) < 3 {
		printUsage(stderr)
		return ExitError
	}
	opt.paths, opt.format, opt.rulesets = positionals[0], positionals[1], positionals[2]
	if err := requireNonEmptyLists(opt); err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	return run(opt, stdout, stderr)
}

// run executes the analysis pipeline for already-parsed options.
func run(opt options, stdout, stderr io.Writer) int {
	rnd, err := selectRenderer(opt)
	if err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	sets, err := loadRuleSets(opt, stderr)
	if err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	applyRuleFilters(opt, sets, stderr)
	rep, err := runner.Run(runner.Options{
		Paths:       splitList(opt.paths),
		RuleSets:    sets,
		Suffixes:    suffixList(opt.suffixes),
		Exclude:     splitList(opt.exclude),
		IgnoreTests: opt.ignoreTests,
	})
	if err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	if err := writeReport(rnd, opt, rep, stdout); err != nil {
		fmt.Fprintln(stderr, "error:", err)
		return ExitError
	}
	return exitCodeFor(rep, opt)
}

// applyRuleFilters narrows the loaded rule sets by name and warns when the
// filter leaves nothing selected or names rules that are not loaded.
func applyRuleFilters(opt options, sets []*rule.RuleSet, stderr io.Writer) {
	enable, disable := splitList(opt.ruleFilter.enable), splitList(opt.ruleFilter.disable)
	if len(enable) == 0 && len(disable) == 0 {
		return
	}
	res := ruleset.ApplyRuleFilter(sets, enable, disable)
	if res.Remaining == 0 {
		fmt.Fprintln(stderr, "warning: no rules selected (check --enable/--only/--disable)")
	}
	if opt.verbose {
		for _, name := range res.Unmatched {
			fmt.Fprintf(stderr, "warning: no rule named %q (check --enable/--only/--disable)\n", name)
		}
	}
}

// handleInfoFlags handles --version/--help, which short-circuit normal runs
// wherever they appear in the argument list, before any other validation.
func handleInfoFlags(args []string, stdout io.Writer) (code int, handled bool) {
	for _, a := range args {
		switch a {
		case "--version":
			fmt.Fprintf(stdout, "messgo %s\n", version.Version)
			return ExitSuccess, true
		case "--help", "-h":
			printUsage(stdout)
			return ExitSuccess, true
		}
	}
	// The bare `help` command is only honoured as the first argument, where it
	// cannot be mistaken for a path.
	if args[0] == "help" {
		printUsage(stdout)
		return ExitSuccess, true
	}
	return 0, false
}

// parseArgs parses options and positional arguments, table-driving the flags.
func parseArgs(args []string) (options, []string, error) {
	opt := options{format: "text", maxPriority: 1}
	var positionals []string
	boolFlags := map[string]*bool{
		"--verbose":                   &opt.verbose,
		"-v":                          &opt.verbose,
		"--strict":                    &opt.strict,
		"--color":                     &opt.color,
		"--ignore-errors-on-exit":     &opt.ignoreErrors,
		"--ignore-violations-on-exit": &opt.ignoreViolations,
		"--ignore-tests":              &opt.ignoreTests,
	}
	strFlags := map[string]*string{
		"--reportfile": &opt.reportFile,
		"--suffixes":   &opt.suffixes,
		"--exclude":    &opt.exclude,
		"--enable":     &opt.ruleFilter.enable,
		"--only":       &opt.ruleFilter.enable, // alias for --enable
		"--disable":    &opt.ruleFilter.disable,
	}
	intFlags := map[string]*int{
		"--minimumpriority": &opt.minPriority,
		"--maximumpriority": &opt.maxPriority,
	}
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case boolFlags[a] != nil:
			*boolFlags[a] = true
		case strFlags[a] != nil || intFlags[a] != nil:
			if err := valueFlag(args, &i, a, valueTarget{str: strFlags[a], pri: intFlags[a]}); err != nil {
				return opt, nil, err
			}
		case strings.HasPrefix(a, "--"):
			return opt, nil, fmt.Errorf("unknown option: %s", a)
		default:
			positionals = append(positionals, a)
		}
	}
	if len(positionals) > 3 {
		return opt, nil, fmt.Errorf("unexpected argument %q", positionals[3])
	}
	return opt, positionals, nil
}

// selectRenderer resolves the requested report format to a renderer.
func selectRenderer(opt options) (report.Renderer, error) {
	if opt.format == "text" && opt.color {
		opt.format = "ansi"
	}
	rnd, ok := report.For(opt.format)
	if !ok {
		return nil, fmt.Errorf("unknown report format %q. Available: %s",
			opt.format, strings.Join(report.Formats(), ", "))
	}
	return rnd, nil
}

// loadRuleSets resolves the requested rulesets, applying priority filters.
func loadRuleSets(opt options, stderr io.Writer) ([]*rule.RuleSet, error) {
	loader := &ruleset.Loader{
		MinPriority: opt.minPriority,
		MaxPriority: opt.maxPriority,
		Verbose:     opt.verbose,
		Warn: func(msg string) {
			fmt.Fprintln(stderr, "warning:", msg)
		},
	}
	return loader.Load(opt.rulesets)
}

// writeReport renders the report to stdout or the configured report file.
func writeReport(rnd report.Renderer, opt options, rep *report.Report, stdout io.Writer) error {
	out := stdout
	if opt.reportFile != "" {
		f, err := os.Create(opt.reportFile)
		if err != nil {
			return err
		}
		defer f.Close()
		out = f
	}
	return rnd.Render(out, rep)
}

// exitCodeFor maps the report onto PHPMD's exit-code convention.
func exitCodeFor(rep *report.Report, opt options) int {
	if len(rep.Errors) > 0 && !opt.ignoreErrors {
		return ExitProcessingError
	}
	if len(rep.Violations) > 0 && !opt.ignoreViolations {
		return ExitViolation
	}
	return ExitSuccess
}

// valueTarget is where a value-taking flag stores its value: either a string
// field or an integer priority field.
type valueTarget struct {
	str *string
	pri *int
}

// valueFlag consumes the value token following flag and stores it in t.
func valueFlag(args []string, i *int, flag string, t valueTarget) error {
	v, err := flagValue(args, i, flag)
	if err != nil {
		return err
	}
	if t.str != nil {
		*t.str = v
		return nil
	}
	n, err := nonNegativeInt(v)
	if err != nil {
		return fmt.Errorf("invalid value for %s: %q", flag, v)
	}
	*t.pri = n
	return nil
}

// flagValue consumes the value token following a value-taking flag. A missing
// token, or one that looks like another option, is a usage error.
func flagValue(args []string, i *int, flag string) (string, error) {
	next := *i + 1
	if next >= len(args) || strings.HasPrefix(args[next], "--") {
		return "", fmt.Errorf("%s requires a value", flag)
	}
	*i = next
	return args[next], nil
}

// nonNegativeInt parses a priority value: a whole number >= 0.
func nonNegativeInt(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0, fmt.Errorf("%q is not a non-negative integer", s)
	}
	return n, nil
}

func requireNonEmptyLists(opt options) error {
	if len(splitList(opt.paths)) == 0 {
		return fmt.Errorf("no paths given")
	}
	if len(splitList(opt.rulesets)) == 0 {
		return fmt.Errorf("no rulesets given")
	}
	return nil
}

func splitList(s string) []string {
	if strings.TrimSpace(s) == "" {
		return nil
	}
	var out []string
	for _, p := range strings.Split(s, ",") {
		trimmed := strings.TrimSpace(p)
		if trimmed != "" {
			out = append(out, trimmed)
		}
	}
	return out
}

func suffixList(s string) []string {
	parts := splitList(s)
	for i, p := range parts {
		if !strings.HasPrefix(p, ".") {
			parts[i] = "." + p
		}
	}
	return parts
}

func printUsage(w io.Writer) {
	fmt.Fprintf(w, `messgo %s — a PHPMD-style mess detector for Go

Usage:
  messgo <paths> <format> <ruleset[,...]> [options]

Arguments:
  paths      Comma-separated files or directories to scan.
  format     Report format: %s
  ruleset    Comma-separated built-in rulesets or ruleset XML files.
             Built-in: %s

Options:
  --minimumpriority <n>          Only rules with priority <= n.
  --maximumpriority <n>          Only rules with priority >= n.
  --reportfile <file>            Write the report to a file.
  --suffixes <list>              File extensions to scan (default: go).
  --exclude <list>               Path substrings to exclude (./ prefixes cleaned).
  --enable, --only <list>        Run only these rules (comma-separated names).
  --disable <list>               Skip these rules (comma-separated names).
  --ignore-tests                 Skip *_test.go files.
  --strict                       Also report suppressed violations.
  --color                        Colorize text output.
  --verbose, -v                  Verbose diagnostics.
  --ignore-errors-on-exit        Exit 0 even if parse errors occurred.
  --ignore-violations-on-exit    Exit 0 even if violations were found.
  --version                      Print version.
  --help, -h                     Show this help.

Exit codes: 0 = clean, 1 = error, 2 = violations found, 3 = processing error.
`, version.Version, strings.Join(report.Formats(), ", "), strings.Join(ruleset.BuiltinNames(), ", "))
}

sources.internal/metrics/metrics.go:
// Package metrics computes the code metrics PHPMD relies on (cyclomatic
// complexity, NPath complexity, lines of code), adapted to the Go AST.
package metrics

import (
	"go/ast"
	"go/scanner"
	"go/token"
	"slices"
)

func ccnIncrement(n ast.Node) int {
	switch s := n.(type) {
	case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt:
		return 1
	case *ast.CaseClause:
		if len(s.List) > 0 { // skip default
			return 1
		}
	case *ast.CommClause:
		if s.Comm != nil { // skip default in select
			return 1
		}
	case *ast.BinaryExpr:
		if s.Op == token.LAND || s.Op == token.LOR {
			return 1
		}
	}
	return 0
}

// CyclomaticComplexity computes the cyclomatic complexity (CCN) of a function
// body. Mirrors pdepend's analyzer: a base of 1 plus one for each decision
// point — if, for, range, case (per case clause, excluding default), and each
// boolean operator (&&, ||). This is the same definition used by the widely
// adopted gocyclo and matches PHPMD's intent on Go code.
func CyclomaticComplexity(body *ast.BlockStmt) int {
	if body == nil {
		return 1
	}
	ccn := 1
	ast.Inspect(body, func(n ast.Node) bool {
		ccn += ccnIncrement(n)
		return true
	})
	return ccn
}

// NPathComplexity computes the NPath complexity (number of acyclic execution
// paths) of a function body using Nejmeh's algorithm, as implemented by
// pdepend's NPathComplexityAnalyzer.
func NPathComplexity(body *ast.BlockStmt) int {
	if body == nil {
		return 1
	}
	return npathStmts(body.List)
}

// NestingDepth computes the maximum control-flow nesting depth within a
// function body — the deepest stack of nested if/for/range/switch/type-switch/
// select statements. This is the "arrow code" smell: deeply nested control
// flow is hard to read and a candidate for early returns or guard clauses. It
// is independent of cyclomatic and NPath complexity, which do not penalise
// nesting. Mirrors the intent of nestif and revive's max-control-nesting.
//
// An else-if chain does not add depth (the chained if sits at the same level as
// its parent); an else block does. Case clauses sit inside their switch/select
// and do not add a level of their own.
func NestingDepth(body *ast.BlockStmt) int {
	if body == nil {
		return 0
	}
	return maxStmtNesting(body.List, 0)
}

func maxStmtNesting(stmts []ast.Stmt, depth int) int {
	m := depth
	for _, s := range stmts {
		if d := nestingDepthStmt(s, depth); d > m {
			m = d
		}
	}
	return m
}

// nestingDepthStmt returns the max nesting depth reachable from s, where depth
// is the nesting level of the block containing s.
func nestingDepthStmt(s ast.Stmt, depth int) int {
	switch n := s.(type) {
	case *ast.IfStmt:
		return nestingDepthIf(n, depth)
	case *ast.ForStmt:
		return maxStmtNesting(n.Body.List, depth+1)
	case *ast.RangeStmt:
		return maxStmtNesting(n.Body.List, depth+1)
	case *ast.SwitchStmt:
		return caseNesting(n.Body.List, depth+1)
	case *ast.TypeSwitchStmt:
		return caseNesting(n.Body.List, depth+1)
	case *ast.SelectStmt:
		return commNesting(n.Body.List, depth+1)
	case *ast.LabeledStmt:
		return nestingDepthStmt(n.Stmt, depth)
	case *ast.BlockStmt:
		return maxStmtNesting(n.List, depth)
	}
	return depth
}

// nestingDepthIf handles the if/else branching rules: the if body and an else
// block sit at depth+1; an else-if chain stays at the parent's depth.
func nestingDepthIf(n *ast.IfStmt, depth int) int {
	m := max(depth+1, maxStmtNesting(n.Body.List, depth+1))
	if n.Else == nil {
		return m
	}
	if blk, ok := n.Else.(*ast.BlockStmt); ok {
		return max(m, maxStmtNesting(blk.List, depth+1))
	}
	// else-if chain: the chained if sits at the same level as its parent.
	return max(m, nestingDepthStmt(n.Else, depth))
}

// caseNesting measures nesting within a switch body, whose direct children are
// CaseClauses. The case body sits at the switch's level (depth), not deeper.
func caseNesting(clauses []ast.Stmt, depth int) int {
	m := depth
	for _, c := range clauses {
		cc, ok := c.(*ast.CaseClause)
		if !ok {
			continue
		}
		if d := maxStmtNesting(cc.Body, depth); d > m {
			m = d
		}
	}
	return m
}

// commNesting measures nesting within a select body, whose direct children are
// CommClauses.
func commNesting(clauses []ast.Stmt, depth int) int {
	m := depth
	for _, c := range clauses {
		cc, ok := c.(*ast.CommClause)
		if !ok {
			continue
		}
		if d := maxStmtNesting(cc.Body, depth); d > m {
			m = d
		}
	}
	return m
}

// CognitiveComplexity computes the cognitive complexity of a function using the
// SonarSource algorithm, as implemented by gocognit (github.com/uudashr/gocognit).
// Unlike cyclomatic complexity, cognitive complexity penalises nesting: a
// control-flow structure nested inside another scores nesting+1, not just 1.
// An else-if chain does not add nesting (the chained if sits at the same level
// as its parent); an else block adds +1. Boolean && and || sequences add 1 per
// operator change. Direct recursion adds +1. Labeled break/continue adds +1.
func CognitiveComplexity(fn *ast.FuncDecl) int {
	if fn == nil {
		return 0
	}
	v := &cognitiveVisitor{name: fn.Name}
	ast.Walk(v, fn)
	return v.complexity
}

type cognitiveVisitor struct {
	name            *ast.Ident
	complexity      int
	nesting         int
	elseNodes       map[ast.Node]bool
	calculatedExprs map[ast.Expr]bool
}

func (v *cognitiveVisitor) inc()        { v.complexity++ }
func (v *cognitiveVisitor) nestInc()    { v.complexity += v.nesting + 1 }
func (v *cognitiveVisitor) incNesting() { v.nesting++ }
func (v *cognitiveVisitor) decNesting() { v.nesting-- }

func (v *cognitiveVisitor) markElse(n ast.Node) {
	if v.elseNodes == nil {
		v.elseNodes = make(map[ast.Node]bool)
	}
	v.elseNodes[n] = true
}

func (v *cognitiveVisitor) isElse(n ast.Node) bool {
	return v.elseNodes != nil && v.elseNodes[n]
}

func (v *cognitiveVisitor) markCalc(e ast.Expr) {
	if v.calculatedExprs == nil {
		v.calculatedExprs = make(map[ast.Expr]bool)
	}
	v.calculatedExprs[e] = true
}

func (v *cognitiveVisitor) isCalc(e ast.Expr) bool {
	return v.calculatedExprs != nil && v.calculatedExprs[e]
}

func (v *cognitiveVisitor) walkIfSet(n ast.Node) {
	if n != nil {
		ast.Walk(v, n)
	}
}

// Visit implements ast.Visitor. It handles nesting-increasing nodes (if, switch,
// for, range, select, func-lit) and delegates non-nesting nodes (branch, binary,
// call) to visitNonNesting.
func (v *cognitiveVisitor) Visit(n ast.Node) ast.Visitor {
	switch n := n.(type) {
	case *ast.IfStmt:
		return v.visitIf(n)
	case *ast.SwitchStmt:
		v.visitSwitch(n.Init, n.Tag, n.Body)
		return nil
	case *ast.TypeSwitchStmt:
		v.visitSwitch(n.Init, n.Assign, n.Body)
		return nil
	case *ast.SelectStmt:
		v.nestInc()
		v.incNesting()
		ast.Walk(v, n.Body)
		v.decNesting()
		return nil
	case *ast.ForStmt:
		v.nestInc()
		v.walkIfSet(n.Init)
		v.walkIfSet(n.Cond)
		v.walkIfSet(n.Post)
		v.incNesting()
		ast.Walk(v, n.Body)
		v.decNesting()
		return nil
	case *ast.RangeStmt:
		v.nestInc()
		ast.Walk(v, n.X)
		v.incNesting()
		ast.Walk(v, n.Body)
		v.decNesting()
		return nil
	case *ast.FuncLit:
		v.incNesting()
		ast.Walk(v, n.Body)
		v.decNesting()
		return nil
	}
	return v.visitNonNesting(n)
}

func (v *cognitiveVisitor) visitNonNesting(n ast.Node) ast.Visitor {
	switch n := n.(type) {
	case *ast.BranchStmt:
		if n.Label != nil {
			v.inc()
		}
		return v
	case *ast.BinaryExpr:
		v.visitBinary(n)
		return v
	case *ast.CallExpr:
		v.visitCall(n)
		return v
	}
	return v
}

func (v *cognitiveVisitor) visitIf(n *ast.IfStmt) ast.Visitor {
	if v.isElse(n) {
		v.inc()
	} else {
		v.nestInc()
	}
	v.walkIfSet(n.Init)
	ast.Walk(v, n.Cond)
	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()
	if blk, ok := n.Else.(*ast.BlockStmt); ok {
		v.inc() // +1 for the else keyword
		ast.Walk(v, blk)
	} else if _, ok := n.Else.(*ast.IfStmt); ok {
		v.markElse(n.Else)
		ast.Walk(v, n.Else)
	}
	return nil
}

func (v *cognitiveVisitor) visitSwitch(init ast.Stmt, extra ast.Node, body *ast.BlockStmt) {
	v.nestInc()
	v.walkIfSet(init)
	if extra != nil {
		ast.Walk(v, extra)
	}
	v.incNesting()
	ast.Walk(v, body)
	v.decNesting()
}

func (v *cognitiveVisitor) visitBinary(n *ast.BinaryExpr) {
	if !(n.Op == token.LAND || n.Op == token.LOR) {
		return
	}
	if v.isCalc(n) {
		return
	}
	ops := v.collectBinaryOps(n)
	var lastOp token.Token
	for _, op := range ops {
		if lastOp != op {
			v.inc()
			lastOp = op
		}
	}
}

func (v *cognitiveVisitor) collectBinaryOps(e ast.Expr) []token.Token {
	v.markCalc(e)
	if be, ok := e.(*ast.BinaryExpr); ok {
		return mergeBinaryOps(v.collectBinaryOps(be.X), be.Op, v.collectBinaryOps(be.Y))
	}
	return nil
}

func mergeBinaryOps(x []token.Token, op token.Token, y []token.Token) []token.Token {
	var out []token.Token
	out = append(out, x...)
	if op == token.LAND || op == token.LOR {
		out = append(out, op)
	}
	out = append(out, y...)
	return out
}

func (v *cognitiveVisitor) visitCall(n *ast.CallExpr) {
	if v.name == nil {
		return
	}
	id, ok := n.Fun.(*ast.Ident)
	if !ok {
		return
	}
	if id.Obj == v.name.Obj && id.Name == v.name.Name {
		v.inc() // direct recursion
	}
}

func npathStmts(stmts []ast.Stmt) int {
	product := 1
	for _, s := range stmts {
		product = npathMul(product, npathStmt(s))
	}
	return product
}

func returnStmtComplexity(n *ast.ReturnStmt) int {
	// pdepend visitReturnStatement: NP(return) = E(expr), the raw boolean
	// operator sum seeded from 0. A sum of 0 contributes no paths and falls
	// back to 1 so the statement product is not zeroed.
	c := 0
	for _, r := range n.Results {
		c = npathAdd(c, expressionComplexity(r))
	}
	fl := funcLitsComplexity(n)
	if c == 0 {
		return fl
	}
	return npathMul(c, fl)
}

// funcLitsComplexity computes the combined NPath complexity contributed by any
// func literals directly contained within n, multiplying their body execution
// paths. Does not descend into nested func literals during traversal, as their
// bodies are evaluated recursively by NPathComplexity.
func funcLitsComplexity(n ast.Node) int {
	if n == nil {
		return 1
	}
	prod := 1
	ast.Inspect(n, func(node ast.Node) bool {
		if lit, ok := node.(*ast.FuncLit); ok {
			prod = npathMul(prod, NPathComplexity(lit.Body))
			return false
		}
		return true
	})
	return prod
}

func npathMaxInt() int { return int(^uint(0) >> 1) }

func npathAdd(a, b int) int {
	if a < 0 || b < 0 {
		return npathMaxInt()
	}
	max := npathMaxInt()
	if a > max-b {
		return max
	}
	return a + b
}

func npathMul(a, b int) int {
	if a < 0 || b < 0 {
		return npathMaxInt()
	}
	if a == 0 || b == 0 {
		return 0
	}
	max := npathMaxInt()
	if a > max/b {
		return max
	}
	return a * b
}

func npathSwitchOrSelect(s ast.Stmt) (int, bool) {
	switch n := s.(type) {
	case *ast.SwitchStmt:
		return npathSwitchStmt(n), true
	case *ast.TypeSwitchStmt:
		return npathTypeSwitch(n), true
	case *ast.SelectStmt:
		return npathSelect(n.Body), true
	}
	return 0, false
}

// npathSwitchStmt extends pdepend's switch handling with the Go initializer:
// boolean operators in an init assignment add paths, and func literals in the
// initializer or tag run on every path through the switch, so their paths
// multiply the result.
func npathSwitchStmt(n *ast.SwitchStmt) int {
	npath := npathAdd(npathSwitch(n.Body, n.Tag), assignExprComplexity(n.Init))
	return npathMul(npath, npathMul(funcLitsComplexity(n.Init), funcLitsComplexity(n.Tag)))
}

// npathTypeSwitch mirrors npathSwitchStmt for a type switch, whose guard is an
// assignment rather than a tag expression.
func npathTypeSwitch(n *ast.TypeSwitchStmt) int {
	npath := npathAdd(npathSwitch(n.Body, nil), assignExprComplexity(n.Init))
	return npathMul(npath, npathMul(funcLitsComplexity(n.Init), funcLitsComplexity(n.Assign)))
}

func npathStmt(s ast.Stmt) int {
	if val, ok := npathSwitchOrSelect(s); ok {
		return val
	}
	switch n := s.(type) {
	case *ast.IfStmt:
		return npathIf(n)
	case *ast.ForStmt:
		return npathFor(n)
	case *ast.RangeStmt:
		// pdepend visitForeachStatement: E(iterable) + 1 + NP(body).
		npath := npathAdd(expressionComplexity(n.X), 1)
		return npathAdd(npath, npathStmts(n.Body.List))
	case *ast.BlockStmt:
		return npathStmts(n.List)
	case *ast.LabeledStmt:
		return npathStmt(n.Stmt)
	case *ast.ReturnStmt:
		return returnStmtComplexity(n)
	default:
		return funcLitsComplexity(s)
	}
}

// npathIf implements the NPath formula for if/else chains:
//
//	NP(if) = (NP(else-part) + NP(if-body) + Σ expr + Σ init-expr) × NP(closures)
//
// where the closure factor folds execution paths of func literals declared in
// the initializer or invoked in the condition — they run on every path through
// the if, so their paths multiply the result.
func npathIf(n *ast.IfStmt) int {
	expr := expressionComplexity(n.Cond)
	body := npathStmts(n.Body.List)
	var elsePart int
	switch e := n.Else.(type) {
	case nil:
		elsePart = 1 // implicit empty else
	case *ast.IfStmt:
		elsePart = npathIf(e)
	case *ast.BlockStmt:
		elsePart = npathStmts(e.List)
	default:
		elsePart = npathStmt(e)
	}
	npath := npathAdd(elsePart, body)
	npath = npathAdd(npath, expr)
	npath = npathAdd(npath, assignExprComplexity(n.Init))
	return npathMul(npath, npathMul(funcLitsComplexity(n.Init), funcLitsComplexity(n.Cond)))
}

// assignExprComplexity returns the boolean-operator complexity of the right
// hand side of an assignment statement, as npathFor's loop initialisers and
// post statements are measured. Non-assignments contribute 0.
func assignExprComplexity(s ast.Stmt) int {
	a, ok := s.(*ast.AssignStmt)
	if !ok {
		return 0
	}
	npath := 0
	for _, e := range a.Rhs {
		npath = npathAdd(npath, expressionComplexity(e))
	}
	return npath
}

// npathFor follows pdepend visitForStatement: 1 + Σ E(loop expressions) +
// NP(body). Init/Cond/Post each contribute their boolean-op complexity.
func npathFor(n *ast.ForStmt) int {
	npath := 1
	npath = npathAdd(npath, expressionComplexity(n.Cond))
	npath = npathAdd(npath, assignExprComplexity(n.Init))
	npath = npathAdd(npath, assignExprComplexity(n.Post))
	return npathAdd(npath, npathStmts(n.Body.List))
}

// npathSwitch follows pdepend visitSwitchStatement: E(tag) plus the sum over
// each case/default label of the NPath of that label's body. There is no
// special handling for a missing default — a default is just another label.
func npathSwitch(body *ast.BlockStmt, tag ast.Expr) int {
	npath := expressionComplexity(tag)
	for _, c := range body.List {
		if cc, ok := c.(*ast.CaseClause); ok {
			npath = npathAdd(npath, npathStmts(cc.Body))
		}
	}
	if npath == 0 {
		return 1
	}
	return npath
}

// npathSelect treats each comm clause like a switch label.
func npathSelect(body *ast.BlockStmt) int {
	npath := 0
	for _, c := range body.List {
		if cc, ok := c.(*ast.CommClause); ok {
			npath = npathAdd(npath, npathStmts(cc.Body))
		}
	}
	if npath == 0 {
		npath = 1
	}
	return npath
}

// expressionComplexity counts the boolean operators in an expression, which
// add execution paths (each && or || adds one), matching pdepend. Func literal
// bodies are excluded here because their execution paths are attributed via
// NPathComplexity on the closure body.
func expressionComplexity(e ast.Expr) int {
	if e == nil {
		return 0
	}
	count := 0
	ast.Inspect(e, func(n ast.Node) bool {
		if _, ok := n.(*ast.FuncLit); ok {
			return false
		}
		if b, ok := n.(*ast.BinaryExpr); ok {
			if b.Op == token.LAND || b.Op == token.LOR {
				count++
			}
		}
		return true
	})
	return count
}

// LinesOfCode returns the number of source lines spanned by a node, inclusive
// of the start and end lines — PHPMD's `loc` metric.
func LinesOfCode(fset *token.FileSet, start, end token.Pos) int {
	return fset.Position(end).Line - fset.Position(start).Line + 1
}

// EffectiveLinesOfCode counts only lines that carry code within the span,
// skipping blank and comment-only lines — PHPMD's `eloc` metric (used by the
// ignore-whitespace option). Comments are recognised by the Go scanner, so
// comment markers inside string literals never start a comment.
func EffectiveLinesOfCode(fset *token.FileSet, start, end token.Pos, src []byte) int {
	return NewEffectiveLOCIndex(src).LinesOfCode(fset, start, end)
}

// EffectiveLOCIndex answers effective-lines-of-code queries after one source
// scan. Each prefix entry is the number of code-bearing lines through that
// physical source line.
type EffectiveLOCIndex struct {
	prefix []int
}

// NewEffectiveLOCIndex scans src once and builds an effective-LOC prefix index.
func NewEffectiveLOCIndex(src []byte) *EffectiveLOCIndex {
	lines := splitLines(maskComments(src))
	index := &EffectiveLOCIndex{prefix: make([]int, len(lines)+1)}
	for line, raw := range lines {
		index.prefix[line+1] = index.prefix[line]
		if lineHasCode(raw) {
			index.prefix[line+1]++
		}
	}
	return index
}

// LinesOfCode returns the effective code-line count in the inclusive source
// span. Positions use physical lines so //line directives do not alter spans.
func (index *EffectiveLOCIndex) LinesOfCode(fset *token.FileSet, start, end token.Pos) int {
	if index == nil {
		return 0
	}
	first := max(fset.PositionFor(start, false).Line, 1)
	lineCount := len(index.prefix) - 1
	last := min(fset.PositionFor(end, false).Line, lineCount)
	if last < first {
		return 0
	}
	return index.prefix[last] - index.prefix[first-1]
}

// splitLines splits source into individual lines without their terminators.
func splitLines(src []byte) [][]byte {
	var lines [][]byte
	start := 0
	for i := range len(src) {
		if src[i] == '\n' {
			lines = append(lines, src[start:i])
			start = i + 1
		}
	}
	lines = append(lines, src[start:])
	return lines
}

// maskComments returns a copy of src with every Go comment replaced by
// spaces, newlines inside block comments preserved so the line layout does
// not change. Comments are located with the Go scanner's own tokenizer, so
// comment-like text inside string literals is never mistaken for a comment.
func maskComments(src []byte) []byte {
	masked := make([]byte, len(src))
	copy(masked, src)
	var fset token.FileSet
	file := fset.AddFile("", fset.Base(), len(src))
	var s scanner.Scanner
	s.Init(file, src, nil /* eh */, scanner.ScanComments)
	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			return masked
		}
		if tok != token.COMMENT {
			continue
		}
		start := file.Offset(pos)
		for i := start; i < start+len(lit) && i < len(masked); i++ {
			if masked[i] != '\n' {
				masked[i] = ' '
			}
		}
	}
}

func isNonWhitespace(ch byte) bool {
	return ch != ' ' && ch != '\t' && ch != '\r'
}

// lineHasCode reports whether a line contains any non-whitespace byte. The
// input is the comment-masked source, so no comment handling is needed here.
func lineHasCode(line []byte) bool {
	return slices.ContainsFunc(line, isNonWhitespace)
}

sources.internal/model/build.go:
package model

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"strings"

	"github.com/quality-gates/messgo/internal/util"
)

// Parse reads and parses a Go source file into a File model.
func Parse(path string) (*File, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return ParseSource(path, src)
}

// ParseSource parses Go source bytes into a File model.
func ParseSource(path string, src []byte) (*File, error) {
	fset := token.NewFileSet()
	syntax, err := parser.ParseFile(fset, path, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, err
	}
	f := &File{
		Path:    path,
		Fset:    fset,
		Syntax:  syntax,
		Src:     src,
		Package: syntax.Name.Name,
	}
	b := &fileBuilder{
		f:       f,
		classes: map[string]*Class{},
		ifaces:  map[string]*Interface{},
	}
	b.build()
	return f, nil
}

type fileBuilder struct {
	f       *File
	classes map[string]*Class
	ifaces  map[string]*Interface
	// aliases maps type-alias names in this file to the type they denote, so
	// a method on an alias receiver attaches to the aliased type.
	aliases map[string]string
}

func (b *fileBuilder) line(p token.Pos) int { return b.f.Fset.Position(p).Line }

func (b *fileBuilder) build() {
	b.aliases = util.TypeAliasNames([]*ast.File{b.f.Syntax})
	b.collectTypes()
	b.collectFuncs()
}

func (b *fileBuilder) collectTypes() {
	for _, decl := range b.f.Syntax.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.TYPE {
			continue
		}
		for _, spec := range gen.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			b.collectTypeSpec(ts, gen.Doc)
		}
	}
}

func (b *fileBuilder) collectTypeSpec(ts *ast.TypeSpec, docGroup *ast.CommentGroup) {
	doc := docText(ts.Doc, docGroup)
	switch t := ts.Type.(type) {
	case *ast.StructType:
		c := &Class{
			Name:       ts.Name.Name,
			Line:       b.line(ts.Pos()),
			EndLine:    b.line(ts.End()),
			Exported:   ts.Name.IsExported(),
			File:       b.f,
			Spec:       ts,
			Struct:     t,
			DocComment: doc,
		}
		b.collectFields(c, t)
		b.classes[c.Name] = c
		b.f.Classes = append(b.f.Classes, c)
	case *ast.InterfaceType:
		i := &Interface{
			Name:       ts.Name.Name,
			Line:       b.line(ts.Pos()),
			EndLine:    b.line(ts.End()),
			Exported:   ts.Name.IsExported(),
			File:       b.f,
			Spec:       ts,
			Iface:      t,
			DocComment: doc,
		}
		b.collectInterfaceMethods(i, t)
		b.ifaces[i.Name] = i
		b.f.Interfaces = append(b.f.Interfaces, i)
	}
}

func (b *fileBuilder) collectFuncs() {
	for _, decl := range b.f.Syntax.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		fn := b.buildFunc(fd)
		b.f.AllFuncs = append(b.f.AllFuncs, fn)
		if !fn.IsMethod() {
			b.f.Functions = append(b.f.Functions, fn)
			continue
		}
		if c := b.classes[util.ResolveTypeAlias(b.aliases, fn.Receiver)]; c != nil {
			c.Methods = append(c.Methods, fn)
			fn.Class = c
		}
	}
}

func (b *fileBuilder) collectFields(c *Class, st *ast.StructType) {
	if st.Fields == nil {
		return
	}
	for _, fld := range st.Fields.List {
		typeStr := exprString(fld.Type)
		if len(fld.Names) == 0 {
			// Embedded field: the type name is the field name.
			name := embeddedName(fld.Type)
			c.Embeds = append(c.Embeds, embeddedTypeName(fld.Type))
			c.Fields = append(c.Fields, &Field{
				Name:     name,
				Type:     typeStr,
				TypeExpr: fld.Type,
				Line:     b.line(fld.Pos()),
				Exported: ast.IsExported(name),
			})
			continue
		}
		for _, n := range fld.Names {
			c.Fields = append(c.Fields, &Field{
				Name:     n.Name,
				Type:     typeStr,
				TypeExpr: fld.Type,
				Line:     b.line(n.Pos()),
				Exported: n.IsExported(),
				Ident:    n,
			})
		}
	}
}

func (b *fileBuilder) collectInterfaceMethods(i *Interface, it *ast.InterfaceType) {
	if it.Methods == nil {
		return
	}
	for _, m := range it.Methods.List {
		if len(m.Names) == 0 {
			i.Embeds = append(i.Embeds, exprString(m.Type))
			continue
		}
		ft, _ := m.Type.(*ast.FuncType)
		for _, n := range m.Names {
			fn := &Function{
				Name:     n.Name,
				Receiver: i.Name,
				Line:     b.line(n.Pos()),
				EndLine:  b.line(m.End()),
				Exported: n.IsExported(),
				File:     b.f,
			}
			if ft != nil {
				fn.Params = b.params(ft.Params)
				fn.Results = b.params(ft.Results)
			}
			i.Methods = append(i.Methods, fn)
		}
	}
}

func (b *fileBuilder) buildFunc(fd *ast.FuncDecl) *Function {
	fn := &Function{
		Name:       fd.Name.Name,
		Line:       b.line(fd.Pos()),
		EndLine:    b.line(fd.End()),
		Exported:   fd.Name.IsExported(),
		Decl:       fd,
		Body:       fd.Body,
		File:       b.f,
		DocComment: docText(fd.Doc),
	}
	if fd.Type != nil {
		fn.Params = b.params(fd.Type.Params)
		fn.Results = b.params(fd.Type.Results)
	}
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		r := fd.Recv.List[0]
		fn.Receiver = receiverTypeName(r.Type)
		if len(r.Names) > 0 {
			fn.RecvName = r.Names[0].Name
		}
	}
	return fn
}

func (b *fileBuilder) params(fl *ast.FieldList) []*Parameter {
	if fl == nil {
		return nil
	}
	var out []*Parameter
	for _, fld := range fl.List {
		typeStr := exprString(fld.Type)
		if len(fld.Names) == 0 {
			out = append(out, &Parameter{Type: typeStr, Line: b.line(fld.Pos()), Field: fld})
			continue
		}
		for _, n := range fld.Names {
			out = append(out, &Parameter{
				Name:  n.Name,
				Type:  typeStr,
				Line:  b.line(n.Pos()),
				Field: fld,
				Ident: n,
			})
		}
	}
	return out
}

func receiverTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return receiverTypeName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr: // generic receiver Foo[T]
		return receiverTypeName(t.X)
	case *ast.IndexListExpr:
		return receiverTypeName(t.X)
	}
	return ""
}

func embeddedName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return embeddedName(t.X)
	case *ast.ParenExpr:
		return embeddedName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return t.Sel.Name
	case *ast.IndexExpr:
		return embeddedName(t.X)
	case *ast.IndexListExpr:
		return embeddedName(t.X)
	}
	return exprString(e)
}

func embeddedTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return embeddedTypeName(t.X)
	case *ast.ParenExpr:
		return embeddedTypeName(t.X)
	case *ast.IndexExpr:
		return embeddedTypeName(t.X)
	case *ast.IndexListExpr:
		return embeddedTypeName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	}
	return exprString(e)
}

func docText(groups ...*ast.CommentGroup) string {
	for _, g := range groups {
		if g != nil {
			return g.Text()
		}
	}
	return ""
}

// exprString renders a type expression to a compact string. It avoids
// go/printer to keep things dependency-free and stable.
func exprString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	case *ast.ArrayType:
		return arrayTypeString(t)
	case *ast.ChanType:
		return chanTypeString(t)
	case *ast.ParenExpr:
		return exprString(t.X)
	default:
		return exprStringOther(t)
	}
}

func arrayTypeString(t *ast.ArrayType) string {
	return "[" + exprString(t.Len) + "]" + exprString(t.Elt)
}

func chanTypeString(t *ast.ChanType) string {
	switch t.Dir {
	case ast.SEND:
		return "chan<- " + exprString(t.Value)
	case ast.RECV:
		return "<-chan " + exprString(t.Value)
	default:
		return "chan " + exprString(t.Value)
	}
}

func exprStringOther(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.BasicLit:
		return t.Value
	case *ast.MapType:
		return "map[" + exprString(t.Key) + "]" + exprString(t.Value)
	case *ast.Ellipsis:
		return "..." + exprString(t.Elt)
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.StructType:
		return "struct{}"
	case *ast.FuncType:
		return "func"
	case *ast.IndexExpr, *ast.IndexListExpr:
		return indexTypeString(t)
	}
	return ""
}

func indexTypeString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.IndexExpr:
		return exprString(t.X) + "[" + exprString(t.Index) + "]"
	case *ast.IndexListExpr:
		parts := make([]string, len(t.Indices))
		for i, ix := range t.Indices {
			parts[i] = exprString(ix)
		}
		return exprString(t.X) + "[" + strings.Join(parts, ",") + "]"
	}
	return ""
}

sources.internal/model/member_selection.go:
package model

import (
	"go/ast"
	"go/token"
)

type memberSelectionCollector struct {
	types    memberTypeResolver
	scope    memberScopeCollector
	recorder memberUseRecorder
}

type memberTypeResolver struct {
	classes    map[string]*Class
	interfaces map[string]*Interface
	functions  map[string]*Function
}

type memberScopeCollector struct {
	resolver *memberTypeResolver
}

type memberUseRecorder struct {
	resolver *memberTypeResolver
}

func collectSelectedMemberUses(f *File) (map[string]bool, map[MemberKey]bool) {
	names := map[string]bool{}
	uses := map[MemberKey]bool{}
	collector := newMemberSelectionCollector(f)
	packageTypes := collector.packageTypes(f)

	ast.Inspect(f.Syntax, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			collector.collectFunc(node, packageTypes, names, uses)
			return false
		case *ast.SelectorExpr:
			collector.recorder.recordSelector(node, packageTypes, names, uses)
		case *ast.CompositeLit:
			collector.recorder.recordComposite(node, names, uses)
		}
		return true
	})
	return names, uses
}

func newMemberSelectionCollector(f *File) *memberSelectionCollector {
	classes := f.Classes
	if f.PackageClasses != nil {
		classes = f.PackageClasses
	}
	classByName := make(map[string]*Class, len(classes))
	for _, class := range classes {
		classByName[class.Name] = class
	}
	ifaces := f.Interfaces
	if f.PackageInterfaces != nil {
		ifaces = f.PackageInterfaces
	}
	ifaceByName := make(map[string]*Interface, len(ifaces))
	for _, iface := range ifaces {
		ifaceByName[iface.Name] = iface
	}
	funcs := f.AllFuncs
	if f.PackageFunctions != nil {
		funcs = f.PackageFunctions
	}
	functions := make(map[string]*Function, len(funcs))
	for _, fn := range funcs {
		if !fn.IsMethod() && functions[fn.Name] == nil {
			functions[fn.Name] = fn
		}
	}
	collector := &memberSelectionCollector{
		types: memberTypeResolver{
			classes:    classByName,
			interfaces: ifaceByName,
			functions:  functions,
		},
	}
	collector.scope.resolver = &collector.types
	collector.recorder.resolver = &collector.types
	return collector
}

func (c *memberSelectionCollector) packageTypes(f *File) map[string]memberVarType {
	types := map[string]memberVarType{}
	for _, decl := range f.Syntax.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.VAR {
			continue
		}
		for _, spec := range gen.Specs {
			value, ok := spec.(*ast.ValueSpec)
			if ok {
				c.scope.addValueSpec(value, types)
			}
		}
	}
	return types
}

func (c *memberSelectionCollector) collectFunc(decl *ast.FuncDecl, packageTypes map[string]memberVarType, names map[string]bool, uses map[MemberKey]bool) {
	types := cloneMemberTypes(packageTypes)
	c.scope.addFuncParameters(decl, types)
	if decl.Body == nil {
		return
	}
	c.scope.collectLocalTypes(decl.Body, types)
	c.collectBody(decl.Body, types, names, uses)
}

func cloneMemberTypes(source map[string]memberVarType) map[string]memberVarType {
	clone := make(map[string]memberVarType, len(source))
	for name, typeName := range source {
		clone[name] = typeName
	}
	return clone
}

func (c *memberScopeCollector) addFuncParameters(decl *ast.FuncDecl, types map[string]memberVarType) {
	if decl.Recv != nil {
		addNamedFieldTypes(decl.Recv.List, types)
	}
	if decl.Type == nil || decl.Type.Params == nil {
		return
	}
	addNamedFieldTypes(decl.Type.Params.List, types)
}

func addNamedFieldTypes(fields []*ast.Field, types map[string]memberVarType) {
	for _, field := range fields {
		fieldType := memberVarTypeOf(field.Type)
		if fieldType.empty() {
			continue
		}
		for _, name := range field.Names {
			types[name.Name] = fieldType
		}
	}
}

func (c *memberScopeCollector) collectLocalTypes(body *ast.BlockStmt, types map[string]memberVarType) {
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncLit:
			return false
		case *ast.DeclStmt:
			c.addDeclaration(node, types)
		case *ast.AssignStmt:
			c.addAssignment(node, types)
		case *ast.RangeStmt:
			c.addRange(node, types)
		}
		return true
	})
}

func (c *memberScopeCollector) addDeclaration(stmt *ast.DeclStmt, types map[string]memberVarType) {
	gen, ok := stmt.Decl.(*ast.GenDecl)
	if !ok || gen.Tok != token.VAR {
		return
	}
	for _, spec := range gen.Specs {
		value, ok := spec.(*ast.ValueSpec)
		if ok {
			c.addValueSpec(value, types)
		}
	}
}

func (c *memberScopeCollector) addValueSpec(spec *ast.ValueSpec, types map[string]memberVarType) {
	declaredType := memberVarTypeOf(spec.Type)
	valueTypes := c.valueSpecRhsTypes(spec, declaredType, types)
	for index, name := range spec.Names {
		if name.Name == "_" || index >= len(valueTypes) {
			continue
		}
		if !valueTypes[index].empty() {
			types[name.Name] = valueTypes[index]
		}
	}
}

func (c *memberScopeCollector) valueSpecRhsTypes(spec *ast.ValueSpec, declaredType memberVarType, types map[string]memberVarType) []memberVarType {
	if !declaredType.empty() {
		result := make([]memberVarType, len(spec.Names))
		for i := range result {
			result[i] = declaredType
		}
		return result
	}
	if len(spec.Values) == 1 && len(spec.Names) > 1 {
		if call, ok := unwrapParen(spec.Values[0]).(*ast.CallExpr); ok {
			return c.resolver.callResultTypes(call, types)
		}
	}
	result := make([]memberVarType, len(spec.Values))
	for i, v := range spec.Values {
		result[i] = c.resolver.resolvedType(v, types)
	}
	return result
}

func (c *memberScopeCollector) addAssignment(stmt *ast.AssignStmt, types map[string]memberVarType) {
	rhsTypes := c.assignmentRhsTypes(stmt, types)
	for index, lhs := range stmt.Lhs {
		name, ok := lhs.(*ast.Ident)
		if !ok || name.Name == "_" || index >= len(rhsTypes) {
			continue
		}
		if !rhsTypes[index].empty() {
			types[name.Name] = rhsTypes[index]
		}
	}
}

func (c *memberScopeCollector) assignmentRhsTypes(stmt *ast.AssignStmt, types map[string]memberVarType) []memberVarType {
	if len(stmt.Rhs) == 1 && len(stmt.Lhs) > 1 {
		if call, ok := unwrapParen(stmt.Rhs[0]).(*ast.CallExpr); ok {
			return c.resolver.callResultTypes(call, types)
		}
	}
	result := make([]memberVarType, len(stmt.Rhs))
	for i, rhs := range stmt.Rhs {
		result[i] = c.resolver.resolvedType(rhs, types)
	}
	return result
}

// addRange binds the iteration variables of a range statement. Which variable
// carries the container's member-bearing type depends on the container: a map
// yields key then value, a sequence yields index then element, and a channel
// yields the element in the first variable.
func (c *memberScopeCollector) addRange(stmt *ast.RangeStmt, types map[string]memberVarType) {
	subject := c.resolver.resolvedType(stmt.X, types)
	switch subject.kind {
	case containerMap:
		bindRangeVar(stmt.Key, memberVarType{name: subject.key}, types)
		bindRangeVar(stmt.Value, memberVarType{name: subject.name}, types)
	case containerSequence:
		bindRangeVar(stmt.Value, memberVarType{name: subject.name}, types)
	case containerChannel:
		bindRangeVar(stmt.Key, memberVarType{name: subject.name}, types)
	default:
		bindRangeVar(rangeElementVar(stmt), memberVarType{name: subject.name}, types)
	}
}

// rangeElementVar picks the variable that holds the element of a container of
// unknown shape, preferring the value variable when the statement has one.
func rangeElementVar(stmt *ast.RangeStmt) ast.Expr {
	if stmt.Value != nil {
		return stmt.Value
	}
	return stmt.Key
}

func bindRangeVar(target ast.Expr, varType memberVarType, types map[string]memberVarType) {
	id, ok := target.(*ast.Ident)
	if !ok || id.Name == "_" || varType.empty() {
		return
	}
	types[id.Name] = varType
}

func (c *memberSelectionCollector) collectBody(body *ast.BlockStmt, types map[string]memberVarType, names map[string]bool, uses map[MemberKey]bool) {
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncLit:
			nestedTypes := cloneMemberTypes(types)
			c.scope.addFuncLiteralParameters(node, nestedTypes)
			c.scope.collectLocalTypes(node.Body, nestedTypes)
			c.collectBody(node.Body, nestedTypes, names, uses)
			return false
		case *ast.SelectorExpr:
			c.recorder.recordSelector(node, types, names, uses)
		case *ast.CompositeLit:
			c.recorder.recordComposite(node, names, uses)
		}
		return true
	})
}

func (c *memberScopeCollector) addFuncLiteralParameters(lit *ast.FuncLit, types map[string]memberVarType) {
	if lit.Type == nil || lit.Type.Params == nil {
		return
	}
	addNamedFieldTypes(lit.Type.Params.List, types)
}

func (c *memberUseRecorder) recordSelector(sel *ast.SelectorExpr, types map[string]memberVarType, names map[string]bool, uses map[MemberKey]bool) {
	name := sel.Sel.Name
	names[name] = true
	if typeName := c.resolver.expressionType(sel.X, types); typeName != "" {
		uses[MemberKey{Type: typeName, Name: name}] = true
		for _, key := range c.resolver.promotedMemberPath(typeName, name) {
			uses[key] = true
		}
	}
}

func (c *memberUseRecorder) recordComposite(lit *ast.CompositeLit, names map[string]bool, uses map[MemberKey]bool) {
	if isCollectionLiteral(lit) {
		return
	}
	typeName := memberTypeName(lit.Type)
	if recordKeyedMembers(lit, typeName, names, uses) {
		return
	}
	if len(lit.Elts) == 0 || typeName == "" {
		return
	}
	c.recordUnkeyedMembers(typeName, lit, names, uses)
}

func isCollectionLiteral(lit *ast.CompositeLit) bool {
	switch lit.Type.(type) {
	case *ast.MapType, *ast.ArrayType:
		return true
	default:
		return false
	}
}

func recordKeyedMembers(lit *ast.CompositeLit, typeName string, names map[string]bool, uses map[MemberKey]bool) bool {
	keyed := false
	for _, elt := range lit.Elts {
		kv, ok := elt.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		keyed = true
		recordKeyedMember(kv, typeName, names, uses)
	}
	return keyed
}

func recordKeyedMember(kv *ast.KeyValueExpr, typeName string, names map[string]bool, uses map[MemberKey]bool) {
	id, ok := kv.Key.(*ast.Ident)
	if !ok {
		return
	}
	names[id.Name] = true
	if typeName != "" {
		uses[MemberKey{Type: typeName, Name: id.Name}] = true
	}
}

func (c *memberUseRecorder) recordUnkeyedMembers(typeName string, lit *ast.CompositeLit, names map[string]bool, uses map[MemberKey]bool) {
	class := c.resolver.classes[typeName]
	if class == nil {
		return
	}
	for _, field := range class.Fields {
		names[field.Name] = true
		uses[MemberKey{Type: typeName, Name: field.Name}] = true
	}
}

// expressionType is the member-bearing type name of an expression, discarding
// the container shape that resolvedType carries.
func (c *memberTypeResolver) expressionType(expr ast.Expr, types map[string]memberVarType) string {
	return c.resolvedType(expr, types).name
}

func (c *memberTypeResolver) resolvedType(expr ast.Expr, types map[string]memberVarType) memberVarType {
	switch node := expr.(type) {
	case *ast.Ident:
		return types[node.Name]
	case *ast.SelectorExpr:
		return c.selectorType(node, types)
	case *ast.CompositeLit:
		return memberVarTypeOf(node.Type)
	case *ast.TypeAssertExpr:
		return memberVarTypeOf(node.Type)
	case *ast.CallExpr:
		return c.callType(node, types)
	default:
		return c.wrappedExpressionType(expr, types)
	}
}

func (c *memberTypeResolver) wrappedExpressionType(expr ast.Expr, types map[string]memberVarType) memberVarType {
	switch node := expr.(type) {
	case *ast.ParenExpr:
		return c.resolvedType(node.X, types)
	case *ast.StarExpr:
		return c.resolvedType(node.X, types)
	case *ast.UnaryExpr:
		return c.resolvedType(node.X, types)
	case *ast.SliceExpr:
		return c.resolvedType(node.X, types)
	case *ast.IndexExpr:
		return elementType(c.resolvedType(node.X, types))
	case *ast.IndexListExpr:
		return elementType(c.resolvedType(node.X, types))
	default:
		return memberVarType{}
	}
}

// elementType drops the container shape: indexing a container yields an element,
// which is no longer that container.
func elementType(container memberVarType) memberVarType {
	return memberVarType{name: container.name}
}

func (c *memberTypeResolver) selectorType(sel *ast.SelectorExpr, types map[string]memberVarType) memberVarType {
	baseType := c.expressionType(sel.X, types)
	if baseType == "" {
		return memberVarType{}
	}
	return c.classMemberType(baseType, sel.Sel.Name)
}

func (c *memberTypeResolver) callType(call *ast.CallExpr, types map[string]memberVarType) memberVarType {
	results := c.callResultTypes(call, types)
	if len(results) == 1 {
		return results[0]
	}
	return memberVarType{}
}

func (c *memberTypeResolver) callResultTypes(call *ast.CallExpr, types map[string]memberVarType) []memberVarType {
	if call == nil {
		return nil
	}
	fun := unwrapParen(call.Fun)
	if id, ok := fun.(*ast.Ident); ok {
		return resolveIdentCall(c.classes, c.functions, id, call.Args)
	}
	if sel, ok := fun.(*ast.SelectorExpr); ok {
		return resolveSelectorCall(c, sel, types)
	}
	return nil
}

func resolveIdentCall(classes map[string]*Class, functions map[string]*Function, id *ast.Ident, args []ast.Expr) []memberVarType {
	if id.Name == "new" && len(args) == 1 {
		if argType := memberVarTypeOf(args[0]); !argType.empty() {
			return []memberVarType{argType}
		}
		return nil
	}
	if _, ok := classes[id.Name]; ok {
		return []memberVarType{{name: id.Name}}
	}
	if fn := functions[id.Name]; fn != nil {
		return functionResultTypes(fn)
	}
	return nil
}

func resolveSelectorCall(r *memberTypeResolver, sel *ast.SelectorExpr, types map[string]memberVarType) []memberVarType {
	baseType := r.expressionType(sel.X, types)
	if baseType == "" {
		return nil
	}
	method := lookupMethod(r.classes, r.interfaces, baseType, sel.Sel.Name, map[string]bool{})
	if method == nil {
		return nil
	}
	return functionResultTypes(method)
}

func lookupMethod(classes map[string]*Class, ifaces map[string]*Interface, typeName, methodName string, visiting map[string]bool) *Function {
	if visiting[typeName] {
		return nil
	}
	visiting[typeName] = true
	defer delete(visiting, typeName)

	if class := classes[typeName]; class != nil {
		if method := classMethod(classes, ifaces, class, methodName, visiting); method != nil {
			return method
		}
	}
	if iface := ifaces[typeName]; iface != nil {
		if method := interfaceMethod(classes, ifaces, iface, methodName, visiting); method != nil {
			return method
		}
	}
	return nil
}

func classMethod(classes map[string]*Class, ifaces map[string]*Interface, class *Class, methodName string, visiting map[string]bool) *Function {
	for _, method := range class.Methods {
		if method.Name == methodName {
			return method
		}
	}
	for _, field := range class.Fields {
		if field.Ident != nil {
			continue
		}
		embeddedType := memberTypeName(field.TypeExpr)
		if method := lookupMethod(classes, ifaces, embeddedType, methodName, visiting); method != nil {
			return method
		}
	}
	return nil
}

func interfaceMethod(classes map[string]*Class, ifaces map[string]*Interface, iface *Interface, methodName string, visiting map[string]bool) *Function {
	for _, method := range iface.Methods {
		if method.Name == methodName {
			return method
		}
	}
	for _, embed := range iface.Embeds {
		if method := lookupMethod(classes, ifaces, embed, methodName, visiting); method != nil {
			return method
		}
	}
	return nil
}

func (c *memberTypeResolver) classMemberType(typeName, memberName string) memberVarType {
	memberType, _, ok := c.lookupMember(typeName, memberName, map[string]bool{})
	if !ok {
		return memberVarType{}
	}
	return memberType
}

func (c *memberTypeResolver) promotedMemberPath(typeName, memberName string) []MemberKey {
	_, path, ok := c.lookupMember(typeName, memberName, map[string]bool{})
	if !ok {
		return nil
	}
	return path
}

func (c *memberTypeResolver) lookupMember(typeName, memberName string, visiting map[string]bool) (memberVarType, []MemberKey, bool) {
	class := c.classes[typeName]
	if class == nil || visiting[typeName] {
		return memberVarType{}, nil, false
	}
	visiting[typeName] = true
	defer delete(visiting, typeName)
	if memberType, ok := directMemberType(class, memberName); ok {
		return memberType, []MemberKey{{Type: typeName, Name: memberName}}, true
	}
	return c.lookupEmbeddedMember(class, typeName, memberName, visiting)
}

func directMemberType(class *Class, memberName string) (memberVarType, bool) {
	for _, field := range class.Fields {
		if field.Name == memberName {
			return memberVarTypeOf(field.TypeExpr), true
		}
	}
	for _, method := range class.Methods {
		if method.Name == memberName {
			return functionResultType(method), true
		}
	}
	return memberVarType{}, false
}

func (c *memberTypeResolver) lookupEmbeddedMember(class *Class, typeName, memberName string, visiting map[string]bool) (memberVarType, []MemberKey, bool) {
	for _, field := range class.Fields {
		if field.Ident != nil {
			continue
		}
		embeddedType := memberTypeName(field.TypeExpr)
		memberType, path, ok := c.lookupMember(embeddedType, memberName, visiting)
		if !ok {
			continue
		}
		path = append([]MemberKey{{Type: typeName, Name: field.Name}}, path...)
		return memberType, path, true
	}
	return memberVarType{}, nil, false
}

func functionResultTypes(fn *Function) []memberVarType {
	if fn == nil || len(fn.Results) == 0 {
		return nil
	}
	results := make([]memberVarType, len(fn.Results))
	for i, res := range fn.Results {
		if res.Field != nil {
			results[i] = memberVarTypeOf(res.Field.Type)
		}
	}
	return results
}

func functionResultType(fn *Function) memberVarType {
	results := functionResultTypes(fn)
	if len(results) == 1 {
		return results[0]
	}
	return memberVarType{}
}

func unwrapParen(expr ast.Expr) ast.Expr {
	for {
		paren, ok := expr.(*ast.ParenExpr)
		if !ok {
			return expr
		}
		expr = paren.X
	}
}

func memberTypeName(expr ast.Expr) string {
	switch node := expr.(type) {
	case *ast.Ident:
		return node.Name
	case *ast.SelectorExpr:
		return exprString(node)
	case *ast.ParenExpr:
		return memberTypeName(node.X)
	case *ast.StarExpr:
		return memberTypeName(node.X)
	case *ast.IndexExpr:
		return memberTypeName(node.X)
	case *ast.IndexListExpr:
		return memberTypeName(node.X)
	default:
		return containerTypeName(expr)
	}
}

// containerKind is the shape of a container type, which decides how a range
// statement over it binds its iteration variables.
type containerKind int

const (
	containerNone containerKind = iota
	containerSequence
	containerMap
	containerChannel
)

// memberVarType is the member-bearing type of an expression. For a container it
// records the element type in name, plus the shape and, for maps, the key type,
// so callers can tell a map key from a map value.
type memberVarType struct {
	name string
	key  string
	kind containerKind
}

func (t memberVarType) empty() bool {
	return t.name == "" && t.key == ""
}

func memberVarTypeOf(expr ast.Expr) memberVarType {
	kind, key := containerShape(expr)
	return memberVarType{name: memberTypeName(expr), key: key, kind: kind}
}

// containerShape reports the container shape of a type expression and, for a
// map, the member-bearing type name of its key.
func containerShape(expr ast.Expr) (containerKind, string) {
	switch node := expr.(type) {
	case *ast.ParenExpr:
		return containerShape(node.X)
	case *ast.StarExpr:
		return containerShape(node.X)
	case *ast.ArrayType:
		return containerSequence, ""
	case *ast.ChanType:
		return containerChannel, ""
	case *ast.MapType:
		return containerMap, memberTypeName(node.Key)
	default:
		return containerNone, ""
	}
}

func containerTypeName(expr ast.Expr) string {
	switch node := expr.(type) {
	case *ast.ArrayType:
		return memberTypeName(node.Elt)
	case *ast.ChanType:
		return memberTypeName(node.Value)
	case *ast.MapType:
		return memberTypeName(node.Value)
	default:
		return ""
	}
}

