// Package report renders rule violations in the output formats PHPMD
// supports: text, xml, json, ansi, github, gitlab, checkstyle, sarif, html.
package report

import (
	"io"

	"github.com/quality-gates/messgo/internal/rule"
	"github.com/quality-gates/messgo/internal/version"
)

// Version is the messgo version reported in machine-readable output.
var Version = version.Version

// ProcessingError is a file that could not be parsed.
type ProcessingError struct {
	File    string
	Message string
}

// Report is the full set of results handed to a renderer.
type Report struct {
	Violations []*rule.Violation
	Errors     []ProcessingError
}

// Renderer writes a Report to a writer.
type Renderer interface {
	Render(w io.Writer, r *Report) error
}

var renderers = map[string]func() Renderer{
	"text":       func() Renderer { return &TextRenderer{} },
	"ansi":       func() Renderer { return &TextRenderer{Colored: true} },
	"xml":        func() Renderer { return &XMLRenderer{} },
	"json":       func() Renderer { return &JSONRenderer{} },
	"github":     func() Renderer { return &GitHubRenderer{} },
	"gitlab":     func() Renderer { return &GitLabRenderer{} },
	"checkstyle": func() Renderer { return &CheckStyleRenderer{} },
	"sarif":      func() Renderer { return &SARIFRenderer{} },
	"html":       func() Renderer { return &HTMLRenderer{} },
}

// For returns the renderer for a PHPMD format identifier.
func For(format string) (Renderer, bool) {
	if ctor, ok := renderers[format]; ok {
		return ctor(), true
	}
	return nil, false
}

// Formats lists the supported renderer identifiers.
func Formats() []string {
	return []string{"text", "xml", "json", "html", "ansi", "github", "gitlab", "checkstyle", "sarif"}
}

sources.internal/rule/base.go:
package rule

import "sync"

// Base holds the metadata that PHPMD loads from a ruleset XML <rule> element.
// Concrete rule logic types embed *Base, so they satisfy the Rule interface
// for free and only implement the Apply* method(s) they care about.
type Base struct {
	RuleName    string
	RuleMessage string
	RulePrio    int
	RuleSet     string
	RuleURL     string
	RuleDesc    string
	RuleSince   string
	RuleProps   Properties
	KnownProps  []string
}

func (b *Base) Name() string        { return b.RuleName }
func (b *Base) Message() string     { return b.RuleMessage }
func (b *Base) Priority() int       { return b.RulePrio }
func (b *Base) SetName() string     { return b.RuleSet }
func (b *Base) ExternalURL() string { return b.RuleURL }
func (b *Base) Description() string { return b.RuleDesc }
func (b *Base) Since() string       { return b.RuleSince }

// BaseRef is implemented by every rule logic type via the embedded *Base. The
// loader uses it to inject metadata after construction.
type BaseRef interface {
	base() *Base
}

// Configurable is implemented by rules that parse typed properties once when
// the ruleset is loaded.
type Configurable interface {
	Configure(Properties) error
}

func (b *Base) base() *Base { return b }

// BaseOf returns the embedded *Base of a rule, or nil if it has none.
func BaseOf(r Rule) *Base {
	if br, ok := r.(BaseRef); ok {
		return br.base()
	}
	return nil
}

// Constructor builds a fresh rule logic instance with an initialized *Base.
type Constructor func() Rule

var (
	registryMu sync.RWMutex
	registry   = map[string]Constructor{}
)

// Register associates a PHPMD rule class name (e.g.
// "PHPMD\\Rule\\CyclomaticComplexity") with a constructor. Called from rule
// packages' init() functions.
func Register(class string, c Constructor) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[class] = c
}

// Lookup returns the constructor for a class name.
func Lookup(class string) (Constructor, bool) {
	registryMu.RLock()
	defer registryMu.RUnlock()
	c, ok := registry[class]
	return c, ok
}

// Registered reports whether a class has a constructor.
func Registered(class string) bool {
	_, ok := Lookup(class)
	return ok
}

// NewBase is a helper for constructors. knownProps names the properties the
// rule reads from ruleset XML.
func NewBase(knownProps ...string) *Base {
	return &Base{RuleProps: Properties{}, KnownProps: knownProps}
}

sources.internal/rule/engine.go:
package rule

import "github.com/quality-gates/messgo/internal/model"

// RuleSet is a named collection of rules (PHPMD\RuleSet).
type RuleSet struct {
	Name        string
	Description string
	Rules       []Rule
}

// Analyze runs all rules in all rule sets against a single parsed file and
// returns the violations found. Dispatch mirrors PHPMD: each rule is invoked
// for every artifact of the kind(s) it is aware of.
func Analyze(file *model.File, sets []*RuleSet) []*Violation {
	var violations []*Violation
	for _, set := range sets {
		for _, r := range set.Rules {
			ctx := &Context{
				File:       file,
				violations: &violations,
				rule:       r,
			}
			if br, ok := r.(BaseRef); ok {
				ctx.props = br.base().RuleProps
			}
			applyRule(ctx, r, file)
		}
	}
	return violations
}

func applyRule(ctx *Context, r Rule, file *model.File) {
	if fr, ok := r.(FileRule); ok {
		fr.ApplyFile(ctx)
	}
	if cr, ok := r.(ClassRule); ok {
		for _, c := range file.Classes {
			cr.ApplyClass(ctx, c)
		}
	}
	if ir, ok := r.(InterfaceRule); ok {
		for _, i := range file.Interfaces {
			ir.ApplyInterface(ctx, i)
		}
	}
	if fr, ok := r.(FuncRule); ok {
		applyFuncRule(ctx, fr, file)
	}
}

// applyFuncRule invokes a function-aware rule once for every function-level
// artifact: free functions, methods (both in AllFuncs), and interface methods
// (which PHPMD also models as methods). Method-only rules guard on
// fn.IsMethod() in their own body.
func applyFuncRule(ctx *Context, fr FuncRule, file *model.File) {
	for _, fn := range file.AllFuncs {
		fr.ApplyFunc(ctx, fn)
	}
	for _, iface := range file.Interfaces {
		for _, fn := range iface.Methods {
			fr.ApplyFunc(ctx, fn)
		}
	}
}

sources.internal/rule/rule.go:
// Package rule defines the rule engine: the Rule interface, violations, rule
// sets, and the report. This mirrors PHPMD's PHPMD\Rule, PHPMD\RuleViolation,
// PHPMD\RuleSet and PHPMD\Report.
package rule

import (
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/quality-gates/messgo/internal/model"
)

// Violation is a single reported rule violation (PHPMD RuleViolation).
type Violation struct {
	Rule        Rule
	File        string
	BeginLine   int
	EndLine     int
	Description string // rendered message
	Args        []any
	Method      string
	Class       string
	Package     string
	Function    string
	Priority    int
	RuleSetName string
}

// Rule is the interface every rule implements (PHPMD\Rule).
type Rule interface {
	Name() string
	Message() string
	Priority() int
	SetName() string
	ExternalURL() string
	Description() string
	// Since returns the phpmd version the analogous rule appeared in.
	Since() string
}

// Properties carries configurable rule properties parsed from ruleset XML.
type Properties map[string]string

func (p Properties) Int(key string, def int) int {
	if v, ok := p[key]; ok {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return def
}

func (p Properties) Float(key string, def float64) float64 {
	if v, ok := p[key]; ok {
		if n, err := strconv.ParseFloat(v, 64); err == nil {
			return n
		}
	}
	return def
}

type DefaultBool = bool

func (p Properties) Bool(key string, def DefaultBool) bool {
	if v, ok := p[key]; ok {
		switch v {
		case "true", "1", "yes", "on":
			return true
		case "false", "0", "no", "off":
			return false
		}
	}
	return def
}

func (p Properties) String(key, def string) string {
	if v, ok := p[key]; ok {
		return v
	}
	return def
}

// Context is handed to each rule during analysis. Rules append violations via
// the helper methods, which mirror PHPMD's addViolation.
type Context struct {
	File       *model.File
	props      Properties
	violations *[]*Violation
	rule       Rule
}

func (c *Context) Props() Properties { return c.props }

// Report records a violation at begin/end lines, with message arguments
// substituted into the rule's message template. Use the typed Report* helpers
// when an artifact is available so class/method/function metadata is captured.
func (c *Context) Report(beginLine, endLine int, args ...any) {
	c.report(beginLine, endLine, "", "", "", args)
}

func (c *Context) report(beginLine, endLine int, class, method, function string, args []any) {
	c.reportInFile(c.File, beginLine, endLine, class, method, function, args)
}

func (c *Context) reportInFile(file *model.File, beginLine, endLine int, class, method, function string, args []any) {
	filePath := c.File.Path
	pkg := c.File.Package
	if file != nil && file.Path != "" {
		filePath = file.Path
		pkg = file.Package
	}
	v := &Violation{
		Rule:        c.rule,
		File:        filePath,
		BeginLine:   beginLine,
		EndLine:     endLine,
		Args:        args,
		Class:       class,
		Method:      method,
		Function:    function,
		Priority:    c.rule.Priority(),
		RuleSetName: c.rule.SetName(),
		Package:     pkg,
		Description: RenderMessage(c.rule.Message(), args),
	}
	*c.violations = append(*c.violations, v)
}

// ReportFunc records a violation against a function or method, capturing
// class/method/function names the way PHPMD does for XML/JSON output.
func (c *Context) ReportFunc(fn *model.Function, args ...any) {
	if fn.IsMethod() {
		c.reportInFile(fn.File, fn.Line, fn.EndLine, fn.Receiver, fn.Name, "", args)
		return
	}
	c.reportInFile(fn.File, fn.Line, fn.EndLine, "", "", fn.Name, args)
}

// ReportFuncAt is like ReportFunc but at a specific line span.
func (c *Context) ReportFuncAt(fn *model.Function, beginLine, endLine int, args ...any) {
	if fn.IsMethod() {
		c.reportInFile(fn.File, beginLine, endLine, fn.Receiver, fn.Name, "", args)
		return
	}
	c.reportInFile(fn.File, beginLine, endLine, "", "", fn.Name, args)
}

// ReportClass records a violation against a class.
func (c *Context) ReportClass(class *model.Class, args ...any) {
	c.report(class.Line, class.EndLine, class.Name, "", "", args)
}

// ReportInterface records a violation against an interface.
func (c *Context) ReportInterface(i *model.Interface, args ...any) {
	c.report(i.Line, i.EndLine, i.Name, "", "", args)
}

// Artifact-aware rule interfaces. A rule implements one or more of these to be
// invoked for the corresponding artifact type (PHPMD ClassAware, MethodAware,
// FunctionAware, InterfaceAware).

type ClassRule interface {
	Rule
	ApplyClass(c *Context, class *model.Class)
}

type InterfaceRule interface {
	Rule
	ApplyInterface(c *Context, iface *model.Interface)
}

// FuncRule applies to every function-level artifact: free functions, methods,
// and interface methods. The model unifies these as *model.Function, so a rule
// that only cares about methods guards on fn.IsMethod() in its own body.
type FuncRule interface {
	Rule
	ApplyFunc(c *Context, fn *model.Function)
}

// FileRule applies once per file (for rules that scan raw syntax).
type FileRule interface {
	Rule
	ApplyFile(c *Context)
}

// placeholderRe matches {0}, {1}, ... message placeholders. Compiled once at
// package load because RenderMessage runs for every reported violation.
var placeholderRe = regexp.MustCompile(`\{(\d+)\}`)

// phpmdRegexRe matches PHPMD's delimited "(pattern)flags" property encoding.
var phpmdRegexRe = regexp.MustCompile(`^\((.*)\)([imsxu]*)$`)

// phpmdSlashRe matches the slash-delimited form `/pattern/flags`.
var phpmdSlashRe = regexp.MustCompile(`^/(.*)/([imsxu]*)$`)

// RenderMessage substitutes {0}, {1}, ... placeholders in a PHPMD message
// template with the provided args.
func RenderMessage(tmpl string, args []any) string {
	return placeholderRe.ReplaceAllStringFunc(tmpl, func(m string) string {
		idx, _ := strconv.Atoi(m[1 : len(m)-1])
		if idx >= 0 && idx < len(args) {
			return toStr(args[idx])
		}
		return m
	})
}

func toStr(v any) string {
	switch t := v.(type) {
	case string:
		return t
	case int:
		return strconv.Itoa(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case float64:
		// PHPMD prints integral floats without a decimal point.
		if t == float64(int64(t)) {
			return strconv.FormatInt(int64(t), 10)
		}
		return strconv.FormatFloat(t, 'f', -1, 64)
	default:
		return ""
	}
}

// SortViolations orders violations by file then begin line, matching PHPMD's
// report ordering.
func SortViolations(vs []*Violation) {
	sort.SliceStable(vs, func(i, j int) bool {
		if vs[i].File != vs[j].File {
			return vs[i].File < vs[j].File
		}
		return vs[i].BeginLine < vs[j].BeginLine
	})
}

// CompileRegex compiles a PHPMD-style regex property of the form "(pattern)i"
// (trailing i flag). Returns nil if empty.
func CompileRegex(pat string) *regexp.Regexp {
	if pat == "" {
		return nil
	}
	// PHPMD encodes regexes as a delimited pattern plus trailing flags, e.g.
	// "(^(set|get|is|has|with))i". Translate to Go's (?i) inline-flag form.
	body, flags := pat, ""
	switch {
	case phpmdRegexRe.MatchString(pat):
		m := phpmdRegexRe.FindStringSubmatch(pat)
		body, flags = m[1], strings.ReplaceAll(m[2], "u", "")
	case phpmdSlashRe.MatchString(pat):
		m := phpmdSlashRe.FindStringSubmatch(pat)
		body, flags = m[1], strings.ReplaceAll(m[2], "u", "")
	}
	if flags != "" {
		body = "(?" + flags + ")" + body
	}
	re, err := regexp.Compile(body)
	if err != nil {
		return nil
	}
	return re
}

sources.internal/rule/threshold.go:
package rule

import (
	"fmt"
	"strconv"

	"github.com/quality-gates/messgo/internal/model"
)

// Boundary decides whether a measured value violates a configured threshold.
// PHPMD's threshold rules pick one of two boundary conventions; centralising
// them here keeps the off-by-one decision in exactly one place instead of
// re-deriving "<" vs "<=" per rule.
type Boundary int

const (
	// AtOrAbove violates when value >= threshold. Metric rules such as
	// cyclomatic complexity, NPath, and length use this form (PHPMD's
	// "value < threshold" skip).
	AtOrAbove Boundary = iota
	// Above violates when value > threshold. Counting rules such as the
	// TooMany* family use this form (PHPMD's "value <= threshold" skip).
	Above
)

// Violates reports whether value breaches threshold under this boundary.
func (b Boundary) Violates(value, threshold int) bool {
	if b == Above {
		return value > threshold
	}
	return value >= threshold
}

// ThresholdNodeKind selects which artifact stream a threshold rule evaluates.
type ThresholdNodeKind int

const (
	ThresholdFunction ThresholdNodeKind = iota
	ThresholdClass
)

// ThresholdMeasurement is the observable metric result for one artifact.
// Args are the rule-specific leading message arguments; ThresholdRule appends
// the measured value and configured threshold in one place.
type ThresholdMeasurement struct {
	Value int
	Args  []any
}

// FuncThresholdMetric measures a function-like artifact.
type FuncThresholdMetric func(*Context, *model.Function) (ThresholdMeasurement, bool)

// ClassThresholdMetric measures a class-like artifact.
type ClassThresholdMetric func(*Context, *model.Class) (ThresholdMeasurement, bool)

// InterfaceThresholdMetric measures an interface artifact.
type InterfaceThresholdMetric func(*Context, *model.Interface) (ThresholdMeasurement, bool)

// ThresholdDeclaration describes the stable configuration for a threshold rule.
type ThresholdDeclaration struct {
	Property    string
	Default     int
	Boundary    Boundary
	NodeKind    ThresholdNodeKind
	FuncMetric  FuncThresholdMetric
	ClassMetric ClassThresholdMetric
	// InterfaceMetric, when non-nil, makes the threshold rule also evaluate
	// interfaces. This is independent of NodeKind: a class rule (NodeKind ==
	// ThresholdClass) may declare an InterfaceMetric to extend the same smell
	// to interfaces without a separate rule. Rules that omit InterfaceMetric
	// short-circuit on interfaces (ApplyInterface is a no-op).
	InterfaceMetric InterfaceThresholdMetric
	// InterfaceProperty and InterfaceDefault configure a separate threshold
	// for the interface metric, since interface thresholds are typically
	// lower than class thresholds. When InterfaceMetric is nil these are
	// ignored. When InterfaceProperty is empty, InterfaceDefault is used.
	InterfaceProperty string
	InterfaceDefault  int
}

// ThresholdRule owns the common read-compare-report skeleton for threshold
// rules. It is configured once by the ruleset loader, then reused during walks.
type ThresholdRule struct {
	decl            ThresholdDeclaration
	threshold       int
	interfaceThresh int
}

// NewThresholdRule creates a threshold rule from its declaration.
func NewThresholdRule(decl ThresholdDeclaration) *ThresholdRule {
	return &ThresholdRule{decl: decl, threshold: decl.Default, interfaceThresh: decl.InterfaceDefault}
}

// PropertyNames returns the threshold property keys this rule reads.
func (r *ThresholdRule) PropertyNames() []string {
	if r == nil {
		return nil
	}
	names := make([]string, 0, 2)
	if r.decl.Property != "" {
		names = append(names, r.decl.Property)
	}
	if r.decl.InterfaceProperty != "" {
		names = append(names, r.decl.InterfaceProperty)
	}
	return names
}

// Configure parses and stores typed threshold configuration once at load time.
func (r *ThresholdRule) Configure(props Properties) error {
	threshold, err := intProperty(props, r.decl.Property, r.decl.Default)
	if err != nil {
		return err
	}
	r.threshold = threshold
	if r.decl.InterfaceMetric != nil {
		propKey := r.decl.InterfaceProperty
		if propKey == "" {
			propKey = r.decl.Property
		}
		ithreshold, err := intProperty(props, propKey, r.decl.InterfaceDefault)
		if err != nil {
			return err
		}
		r.interfaceThresh = ithreshold
	}
	return nil
}

// ApplyFunc evaluates configured function metrics.
func (r *ThresholdRule) ApplyFunc(c *Context, fn *model.Function) {
	if r.decl.NodeKind != ThresholdFunction || r.decl.FuncMetric == nil {
		return
	}
	measurement, ok := r.decl.FuncMetric(c, fn)
	if !ok {
		return
	}
	r.reportFunc(c, fn, measurement)
}

// ApplyClass evaluates configured class metrics.
func (r *ThresholdRule) ApplyClass(c *Context, class *model.Class) {
	if r.decl.NodeKind != ThresholdClass || r.decl.ClassMetric == nil {
		return
	}
	measurement, ok := r.decl.ClassMetric(c, class)
	if !ok {
		return
	}
	r.reportClass(c, class, measurement)
}

// ApplyInterface evaluates the configured interface metric, if any. Rules
// without an InterfaceMetric short-circuit (no-op), so they never fire on
// interfaces even though the method is promoted to them via embedding.
func (r *ThresholdRule) ApplyInterface(c *Context, iface *model.Interface) {
	if r.decl.InterfaceMetric == nil {
		return
	}
	measurement, ok := r.decl.InterfaceMetric(c, iface)
	if !ok {
		return
	}
	r.reportInterface(c, iface, measurement)
}

func (r *ThresholdRule) reportFunc(c *Context, fn *model.Function, measurement ThresholdMeasurement) {
	if !r.decl.Boundary.Violates(measurement.Value, r.threshold) {
		return
	}
	c.ReportFunc(fn, appendThresholdArgs(measurement, r.threshold)...)
}

func (r *ThresholdRule) reportClass(c *Context, class *model.Class, measurement ThresholdMeasurement) {
	if !r.decl.Boundary.Violates(measurement.Value, r.threshold) {
		return
	}
	c.ReportClass(class, appendThresholdArgs(measurement, r.threshold)...)
}

func (r *ThresholdRule) reportInterface(c *Context, iface *model.Interface, measurement ThresholdMeasurement) {
	if !r.decl.Boundary.Violates(measurement.Value, r.interfaceThresh) {
		return
	}
	c.ReportInterface(iface, appendThresholdArgs(measurement, r.interfaceThresh)...)
}

func appendThresholdArgs(measurement ThresholdMeasurement, threshold int) []any {
	args := make([]any, 0, len(measurement.Args)+2)
	args = append(args, measurement.Args...)
	args = append(args, measurement.Value, threshold)
	return args
}

func intProperty(props Properties, key string, def int) (int, error) {
	raw, ok := props[key]
	if !ok || raw == "" {
		return def, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return 0, fmt.Errorf("invalid integer property %q=%q: %w", key, raw, err)
	}
	return n, nil
}

sources.internal/rules/cleancode/cleancode.go:
// Package cleancode implements PHPMD's Clean Code ruleset, adapted to Go.
// PHP-only rules (StaticAccess, ErrorControlOperator, MissingImport,
// UndefinedVariable) have no Go analog — Go's compiler already enforces the
// equivalents — and are omitted.
package cleancode

import (
	"github.com/quality-gates/messgo/internal/model"
	"github.com/quality-gates/messgo/internal/rule"
	"github.com/quality-gates/messgo/internal/util"
)

func init() {
	rule.Register("PHPMD\\Rule\\CleanCode\\BooleanArgumentFlag", newBooleanArgumentFlag)
	rule.Register("PHPMD\\Rule\\CleanCode\\ElseExpression", func() rule.Rule { return &ElseExpression{Base: rule.NewBase()} })
	rule.Register("PHPMD\\Rule\\CleanCode\\IfStatementAssignment", func() rule.Rule { return &IfStatementAssignment{Base: rule.NewBase()} })
	rule.Register("PHPMD\\Rule\\CleanCode\\DuplicatedArrayKey", func() rule.Rule { return &DuplicatedArrayKey{Base: rule.NewBase()} })
}

// ----- BooleanArgumentFlag ------------------------------------------------
//
// Flags boolean parameters, which typically signal that a function does two
// things depending on the flag (a Single Responsibility Principle smell).

type BooleanArgumentFlag struct {
	*rule.Base
	exceptions []string
}

func newBooleanArgumentFlag() rule.Rule {
	return &BooleanArgumentFlag{Base: rule.NewBase("exceptions", "ignorepattern")}
}

func (r *BooleanArgumentFlag) Configure(props rule.Properties) error {
	r.exceptions = util.SplitToList(props.String("exceptions", ""))
	return nil
}

func (r *BooleanArgumentFlag) check(c *rule.Context, fn *model.Function) {
	if fn.Receiver != "" && util.Contains(r.exceptions, fn.Receiver) {
		return
	}
	image := fn.Name
	if fn.IsMethod() {
		image = fn.Receiver + "::" + fn.Name
	}
	for _, p := range fn.Params {
		if p.Type == "bool" && p.Name != "" && p.Name != "_" {
			c.ReportFuncAt(fn, p.Line, p.Line, image, p.Name)
		}
	}
}
func (r *BooleanArgumentFlag) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- ElseExpression -----------------------------------------------------

type ElseExpression struct{ *rule.Base }

func (r *ElseExpression) check(c *rule.Context, fn *model.Function) {
	for _, line := range model.ElseBlockLines(fn) {
		c.ReportFuncAt(fn, line, line, fn.Name)
	}
}
func (r *ElseExpression) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- IfStatementAssignment ----------------------------------------------
//
// Flags plain assignment (=) in an if-statement initializer, e.g.
// `if x = f(); x { ... }`. Idiomatic short declarations (:=) are not flagged.

type IfStatementAssignment struct{ *rule.Base }

func (r *IfStatementAssignment) check(c *rule.Context, fn *model.Function) {
	for _, pos := range model.IfAssignmentInitPositions(fn) {
		c.ReportFuncAt(fn, pos.Line, pos.Line, pos.Line, pos.Column)
	}
}
func (r *IfStatementAssignment) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- DuplicatedArrayKey -------------------------------------------------
//
// Flags duplicate constant keys in a composite literal (map or array/slice
// with explicit indices).

type DuplicatedArrayKey struct{ *rule.Base }

func (r *DuplicatedArrayKey) ApplyFile(c *rule.Context) {
	for _, dup := range c.File.PackageDuplicateLiteralKeys() {
		c.Report(dup.Line, dup.Line, dup.Display, dup.FirstLine)
	}
}

func (r *DuplicatedArrayKey) check(c *rule.Context, fn *model.Function) {
	for _, dup := range model.DuplicateLiteralKeys(fn) {
		c.ReportFuncAt(fn, dup.Line, dup.Line, dup.Display, dup.FirstLine)
	}
}
func (r *DuplicatedArrayKey) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

