// Package naming implements PHPMD's Naming ruleset, adapted to Go.
package naming

import (
	"regexp"
	"strings"

	"github.com/quality-gates/messgo/internal/model"
	"github.com/quality-gates/messgo/internal/rule"
	"github.com/quality-gates/messgo/internal/util"
)

func init() {
	rule.Register("PHPMD\\Rule\\Naming\\ShortClassName", newShortClassName)
	rule.Register("PHPMD\\Rule\\Naming\\LongClassName", newLongClassName)
	rule.Register("PHPMD\\Rule\\Naming\\ShortVariable", newShortVariable)
	rule.Register("PHPMD\\Rule\\Naming\\LongVariable", newLongVariable)
	rule.Register("PHPMD\\Rule\\Naming\\ShortMethodName", newShortMethodName)
	rule.Register("PHPMD\\Rule\\Naming\\BooleanGetMethodName", newBooleanGetMethodName)
	rule.Register("PHPMD\\Rule\\Naming\\ConstantNamingConventions", func() rule.Rule { return &ConstantNamingConventions{Base: rule.NewBase()} })
	rule.Register("PHPMD\\Rule\\Naming\\ConstructorWithNameAsEnclosingClass", func() rule.Rule { return &ConstructorWithNameAsEnclosingClass{Base: rule.NewBase()} })
}

// ----- ShortClassName -----------------------------------------------------

type ShortClassName struct {
	*rule.Base
	minimum    int
	exceptions []string
}

func newShortClassName() rule.Rule {
	return &ShortClassName{Base: rule.NewBase("minimum", "exceptions")}
}

func (r *ShortClassName) Configure(props rule.Properties) error {
	r.minimum = props.Int("minimum", 3)
	r.exceptions = util.SplitToList(props.String("exceptions", ""))
	return nil
}

func (r *ShortClassName) check(c *rule.Context, name string, line, end int) {
	if len(name) >= r.minimum {
		return
	}
	if util.Contains(r.exceptions, name) {
		return
	}
	c.Report(line, end, name, r.minimum)
}
func (r *ShortClassName) ApplyClass(c *rule.Context, cl *model.Class) {
	r.check(c, cl.Name, cl.Line, cl.EndLine)
}
func (r *ShortClassName) ApplyInterface(c *rule.Context, i *model.Interface) {
	r.check(c, i.Name, i.Line, i.EndLine)
}

// ----- LongClassName ------------------------------------------------------

type LongClassName struct {
	*rule.Base
	maximum  int
	prefixes []string
	suffixes []string
}

func newLongClassName() rule.Rule {
	return &LongClassName{Base: rule.NewBase("maximum", "subtract-prefixes", "subtract-suffixes")}
}

func (r *LongClassName) Configure(props rule.Properties) error {
	r.maximum = props.Int("maximum", 40)
	r.prefixes = util.SplitToList(props.String("subtract-prefixes", ""))
	r.suffixes = util.SplitToList(props.String("subtract-suffixes", ""))
	return nil
}

func (r *LongClassName) check(c *rule.Context, name string, line, end int) {
	if util.LengthWithoutPrefixesAndSuffixes(name, r.prefixes, r.suffixes) <= r.maximum {
		return
	}
	c.Report(line, end, name, r.maximum)
}
func (r *LongClassName) ApplyClass(c *rule.Context, cl *model.Class) {
	r.check(c, cl.Name, cl.Line, cl.EndLine)
}
func (r *LongClassName) ApplyInterface(c *rule.Context, i *model.Interface) {
	r.check(c, i.Name, i.Line, i.EndLine)
}

// ----- ShortVariable ------------------------------------------------------

type ShortVariable struct {
	*rule.Base
	minimum    int
	exceptions []string
}

func newShortVariable() rule.Rule {
	return &ShortVariable{Base: rule.NewBase("minimum", "exceptions")}
}

func (r *ShortVariable) Configure(props rule.Properties) error {
	r.minimum = props.Int("minimum", 3)
	r.exceptions = util.SplitToList(props.String("exceptions", ""))
	return nil
}

func (r *ShortVariable) checkName(c *rule.Context, name string, line int) {
	if name == "_" || len(name) >= r.minimum {
		return
	}
	if util.Contains(r.exceptions, name) {
		return
	}
	c.Report(line, line, name, r.minimum)
}

func (r *ShortVariable) ApplyClass(c *rule.Context, cl *model.Class) {
	for _, f := range cl.Fields {
		r.checkName(c, f.Name, f.Line)
	}
}

func (r *ShortVariable) checkFunc(c *rule.Context, fn *model.Function) {
	for _, p := range fn.Params {
		if p.Name != "" {
			r.checkName(c, p.Name, p.Line)
		}
	}
	if fn.Body != nil {
		for _, v := range util.LocalVariables(fn.Body, fn.File.Fset) {
			if v.IsLoop { // PHPMD allows short loop counters (for-init context)
				continue
			}
			r.checkName(c, v.Name, v.Line)
		}
	}
}
func (r *ShortVariable) ApplyFunc(c *rule.Context, fn *model.Function) { r.checkFunc(c, fn) }

// ----- LongVariable -------------------------------------------------------

type LongVariable struct {
	*rule.Base
	maximum  int
	prefixes []string
	suffixes []string
}

func newLongVariable() rule.Rule {
	return &LongVariable{Base: rule.NewBase("maximum", "subtract-prefixes", "subtract-suffixes")}
}

func (r *LongVariable) Configure(props rule.Properties) error {
	r.maximum = props.Int("maximum", 20)
	r.prefixes = util.SplitToList(props.String("subtract-prefixes", ""))
	r.suffixes = util.SplitToList(props.String("subtract-suffixes", ""))
	return nil
}

func (r *LongVariable) checkName(c *rule.Context, name string, line int) {
	if util.LengthWithoutPrefixesAndSuffixes(name, r.prefixes, r.suffixes) <= r.maximum {
		return
	}
	c.Report(line, line, name, r.maximum)
}

func (r *LongVariable) ApplyClass(c *rule.Context, cl *model.Class) {
	for _, f := range cl.Fields {
		r.checkName(c, f.Name, f.Line)
	}
}
func (r *LongVariable) checkFunc(c *rule.Context, fn *model.Function) {
	for _, p := range fn.Params {
		if p.Name != "" {
			r.checkName(c, p.Name, p.Line)
		}
	}
	if fn.Body != nil {
		for _, v := range util.LocalVariables(fn.Body, fn.File.Fset) {
			r.checkName(c, v.Name, v.Line)
		}
	}
}
func (r *LongVariable) ApplyFunc(c *rule.Context, fn *model.Function) { r.checkFunc(c, fn) }

// ----- ShortMethodName ----------------------------------------------------

type ShortMethodName struct {
	*rule.Base
	minimum    int
	exceptions []string
}

func newShortMethodName() rule.Rule {
	return &ShortMethodName{Base: rule.NewBase("minimum", "exceptions")}
}

func (r *ShortMethodName) Configure(props rule.Properties) error {
	r.minimum = props.Int("minimum", 3)
	r.exceptions = util.SplitToList(props.String("exceptions", ""))
	return nil
}

func (r *ShortMethodName) check(c *rule.Context, fn *model.Function) {
	if !fn.IsMethod() {
		return
	}
	if len(fn.Name) >= r.minimum {
		return
	}
	if util.Contains(r.exceptions, fn.Name) {
		return
	}
	c.ReportFunc(fn, fn.Receiver, fn.Name, r.minimum)
}
func (r *ShortMethodName) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- BooleanGetMethodName -----------------------------------------------

type BooleanGetMethodName struct {
	*rule.Base
	checkParameterizedMethods bool
}

func newBooleanGetMethodName() rule.Rule {
	return &BooleanGetMethodName{Base: rule.NewBase("checkParameterizedMethods")}
}

func (r *BooleanGetMethodName) Configure(props rule.Properties) error {
	r.checkParameterizedMethods = props.Bool("checkParameterizedMethods", false)
	return nil
}

var getterRe = regexp.MustCompile(`(?i)^_?get`)

func (r *BooleanGetMethodName) check(c *rule.Context, fn *model.Function) {
	if !getterRe.MatchString(fn.Name) {
		return
	}
	if !returnsSingleBool(fn) {
		return
	}
	if !r.checkParameterizedMethods && len(fn.Params) > 0 {
		return
	}
	c.ReportFunc(fn, fn.Name)
}

func returnsSingleBool(fn *model.Function) bool {
	if len(fn.Results) != 1 {
		return false
	}
	return fn.Results[0].Type == "bool"
}
func (r *BooleanGetMethodName) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- ConstantNamingConventions ------------------------------------------
//
// PHPMD requires class constants to be UPPERCASE. Adapted to Go, where the
// idiom is MixedCaps, this flags constant names that contain an underscore
// (i.e. ALL_CAPS or snake_case) — the Go analog of the same intent.

type ConstantNamingConventions struct{ *rule.Base }

func (r *ConstantNamingConventions) ApplyFile(c *rule.Context) {
	for _, cst := range collectConstants(c.File) {
		if strings.Contains(cst.name, "_") {
			c.Report(cst.line, cst.line, cst.name)
		}
	}
}

// ----- ConstructorWithNameAsEnclosingClass --------------------------------
//
// PHP4-style constructors named after the class. Adapted to Go: a method whose
// name equals its receiver type name (a confusing "constructor-like" method).
// The error-interface method Error() string on a type named Error is exempt.

type ConstructorWithNameAsEnclosingClass struct{ *rule.Base }

func (r *ConstructorWithNameAsEnclosingClass) ApplyFunc(c *rule.Context, fn *model.Function) {
	if !fn.IsMethod() {
		return
	}
	if fn.Name != fn.Receiver {
		return
	}
	if isErrorInterfaceMethod(fn) {
		return
	}
	c.ReportFunc(fn)
}

func isErrorInterfaceMethod(fn *model.Function) bool {
	if fn.Name != "Error" {
		return false
	}
	if len(fn.Params) != 0 || len(fn.Results) != 1 {
		return false
	}
	return fn.Results[0].Type == "string"
}

sources.internal/rules/opinionated/opinionated.g:
// Package opinionated implements Go-specific rules that are deliberately NOT
// part of the default `go` ruleset. They flag patterns that are sometimes a
// smell but are common enough in idiomatic Go that they would be noisy by
// default. See docs/adr/0001-go-mess-sign-backlog.md ranks 6-8.
package opinionated

import (
	"bytes"
	"go/ast"
	"go/printer"
	"go/token"
	"strings"

	"github.com/quality-gates/messgo/internal/model"
	"github.com/quality-gates/messgo/internal/rule"
)

func init() {
	rule.Register("messgo\\Rule\\UncheckedTypeAssertion", newUncheckedTypeAssertion)
	rule.Register("messgo\\Rule\\IdenticalBranches", newIdenticalBranches)
	rule.Register("messgo\\Rule\\StructEmbeddingDepth", newStructEmbeddingDepth)
}

// ----- UncheckedTypeAssertion ---------------------------------------------

// UncheckedTypeAssertion flags type assertions used without the comma-ok form
// (v, ok := x.(T)), which panic on a failed assertion. The comma-ok form and
// type switches (switch v := x.(type)) are safe and not flagged. Go-specific
// (no PHPMD analog); mirrors revive's and staticcheck's unchecked-type-assertion
// checks. See docs/adr/0001-go-mess-sign-backlog.md rank 6.
type UncheckedTypeAssertion struct {
	*rule.Base
}

func newUncheckedTypeAssertion() rule.Rule {
	return &UncheckedTypeAssertion{Base: rule.NewBase()}
}

func (r *UncheckedTypeAssertion) ApplyFunc(c *rule.Context, fn *model.Function) {
	if fn.Body == nil {
		return
	}
	safe := collectSafeTypeAssertions(fn.Body)
	fset := c.File.Fset
	ast.Inspect(fn.Body, func(n ast.Node) bool {
		ta, ok := n.(*ast.TypeAssertExpr)
		if !ok || ta.Type == nil || safe[ta] {
			return true
		}
		line := fset.Position(ta.Pos()).Line
		c.ReportFuncAt(fn, line, line, string(fn.NodeType()), fn.Name)
		return true
	})
}

// collectSafeTypeAssertions finds type assertions used in the comma-ok form
// (v, ok := x.(T) or var v, ok = x.(T)) so they can be excluded from the
// unchecked set.
func collectSafeTypeAssertions(body *ast.BlockStmt) map[*ast.TypeAssertExpr]bool {
	safe := map[*ast.TypeAssertExpr]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			if len(n.Lhs) == 2 {
				markSafeTypeAssert(safe, n.Rhs)
			}
		case *ast.ValueSpec:
			if len(n.Names) == 2 {
				markSafeTypeAssert(safe, n.Values)
			}
		}
		return true
	})
	return safe
}

// markSafeTypeAssert marks a type assertion as safe if it is the sole value in
// a comma-ok assignment (2 LHS, 1 RHS).
func markSafeTypeAssert(safe map[*ast.TypeAssertExpr]bool, vals []ast.Expr) {
	if len(vals) != 1 {
		return
	}
	ta, ok := unwrapParen(vals[0]).(*ast.TypeAssertExpr)
	if !ok || ta.Type == nil {
		return
	}
	safe[ta] = true
}

func unwrapParen(e ast.Expr) ast.Expr {
	for {
		paren, ok := e.(*ast.ParenExpr)
		if !ok {
			return e
		}
		e = paren.X
	}
}

// ----- IdenticalBranches --------------------------------------------------

// IdenticalBranches flags if/else and switch cases whose bodies are textually
// identical, which usually indicates copy-pasted logic that belongs in a single
// path. Go-specific (no PHPMD analog); mirrors revive's identical-branches and
// dupSquash. See docs/adr/0001-go-mess-sign-backlog.md rank 7.
type IdenticalBranches struct {
	*rule.Base
}

func newIdenticalBranches() rule.Rule {
	return &IdenticalBranches{Base: rule.NewBase()}
}

func (r *IdenticalBranches) ApplyFunc(c *rule.Context, fn *model.Function) {
	if fn.Body == nil {
		return
	}
	fset := c.File.Fset
	ast.Inspect(fn.Body, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.IfStmt:
			r.checkIfElse(c, fn, n, fset)
		case *ast.SwitchStmt:
			r.checkSwitchCases(c, fn, n, fset)
		}
		return true
	})
}

func (r *IdenticalBranches) checkIfElse(c *rule.Context, fn *model.Function, n *ast.IfStmt, fset *token.FileSet) {
	elseBlock, ok := n.Else.(*ast.BlockStmt)
	if !ok {
		return
	}
	if len(n.Body.List) == 0 {
		return
	}
	if !stmtsEqual(n.Body.List, elseBlock.List, fset) {
		return
	}
	line := fset.Position(elseBlock.Pos()).Line
	c.ReportFuncAt(fn, line, line, string(fn.NodeType()), fn.Name)
}

func (r *IdenticalBranches) checkSwitchCases(c *rule.Context, fn *model.Function, n *ast.SwitchStmt, fset *token.FileSet) {
	cases := switchCases(n.Body)
	reported := map[int]bool{}
	for i := range cases {
		if len(cases[i].Body) == 0 {
			continue
		}
		for j := i + 1; j < len(cases); j++ {
			if len(cases[j].Body) == 0 || reported[j] {
				continue
			}
			if !stmtsEqual(cases[i].Body, cases[j].Body, fset) {
				continue
			}
			reported[j] = true
			line := fset.Position(cases[j].Pos()).Line
			c.ReportFuncAt(fn, line, line, string(fn.NodeType()), fn.Name)
		}
	}
}

func switchCases(body *ast.BlockStmt) []*ast.CaseClause {
	var cases []*ast.CaseClause
	for _, s := range body.List {
		if cc, ok := s.(*ast.CaseClause); ok {
			cases = append(cases, cc)
		}
	}
	return cases
}

// stmtsEqual reports whether two statement lists produce identical formatted
// output, which is a practical test for "the same code".
func stmtsEqual(a, b []ast.Stmt, fset *token.FileSet) bool {
	return formatStmts(a, fset) == formatStmts(b, fset)
}

func formatStmts(stmts []ast.Stmt, fset *token.FileSet) string {
	var buf bytes.Buffer
	for _, s := range stmts {
		printer.Fprint(&buf, fset, s)
	}
	return buf.String()
}

// ----- StructEmbeddingDepth ------------------------------------------------

// StructEmbeddingDepth flags structs whose transitive embedding chain exceeds a
// threshold (default 3). Deep embedding chains make it hard to understand which
// promoted fields and methods a type exposes. Cross-package embeddings are
// approximate (treated as depth-0 leaves, since the AST alone cannot resolve
// them); within-package chains are followed across files. Go-specific (no PHPMD
// analog, but the conceptual cousin of PHPMD's DepthOfInheritance). See
// docs/adr/0001-go-mess-sign-backlog.md rank 8.
type StructEmbeddingDepth struct {
	*rule.Base
	*rule.ThresholdRule
}

func newStructEmbeddingDepth() rule.Rule {
	r := &StructEmbeddingDepth{Base: rule.NewBase()}
	r.ThresholdRule = rule.NewThresholdRule(rule.ThresholdDeclaration{
		Property:    "maxdepth",
		Default:     3,
		Boundary:    rule.Above,
		NodeKind:    rule.ThresholdClass,
		ClassMetric: r.measure,
	})
	return r
}

func (r *StructEmbeddingDepth) measure(c *rule.Context, class *model.Class) (rule.ThresholdMeasurement, bool) {
	classes := c.File.PackageClasses
	if classes == nil {
		classes = c.File.Classes
	}
	byName := classIndex(classes)
	depth := embeddingDepth(class.Name, byName, map[string]bool{})
	return rule.ThresholdMeasurement{Value: depth, Args: []any{string(class.NodeType()), class.Name}}, true
}

func classIndex(classes []*model.Class) map[string]*model.Class {
	m := make(map[string]*model.Class, len(classes))
	for _, c := range classes {
		m[c.Name] = c
	}
	return m
}

// embeddingDepth computes the maximum transitive embedding chain length from
// name, following only within-package structs. visiting provides cycle protection.
func embeddingDepth(name string, byName map[string]*model.Class, visiting map[string]bool) int {
	if strings.Contains(name, ".") || visiting[name] {
		return 0
	}
	c, ok := byName[name]
	if !ok {
		return 0
	}
	visiting[name] = true
	defer delete(visiting, name)
	maxd := 0
	for _, embed := range c.Embeds {
		d := 1 + embeddingDepth(embed, byName, visiting)
		if d > maxd {
			maxd = d
		}
	}
	return maxd
}

sources.internal/rules/unusedcode/unusedcode.go:
// Package unusedcode implements PHPMD's Unused Code ruleset, adapted to Go.
// "private" maps to Go's unexported (lower-cased) identifiers, and usage is
// resolved against the owning type across the analyzed package.
package unusedcode

import (
	"github.com/quality-gates/messgo/internal/model"
	"github.com/quality-gates/messgo/internal/rule"
	"github.com/quality-gates/messgo/internal/util"
)

func init() {
	rule.Register("PHPMD\\Rule\\UnusedPrivateField", func() rule.Rule { return &UnusedPrivateField{Base: rule.NewBase()} })
	rule.Register("PHPMD\\Rule\\UnusedLocalVariable", newUnusedLocalVariable)
	rule.Register("PHPMD\\Rule\\UnusedPrivateMethod", func() rule.Rule { return &UnusedPrivateMethod{Base: rule.NewBase()} })
	rule.Register("PHPMD\\Rule\\UnusedFormalParameter", func() rule.Rule { return &UnusedFormalParameter{Base: rule.NewBase()} })
}

// ----- UnusedPrivateField -------------------------------------------------

type UnusedPrivateField struct{ *rule.Base }

func (r *UnusedPrivateField) ApplyClass(c *rule.Context, class *model.Class) {
	for _, f := range class.Fields {
		if f.Exported || f.Name == "_" {
			continue
		}
		if !c.File.MemberSelectedForType(class.Name, f.Name) {
			c.Report(f.Line, f.Line, f.Name)
		}
	}
}

// ----- UnusedPrivateMethod ------------------------------------------------

type UnusedPrivateMethod struct{ *rule.Base }

func (r *UnusedPrivateMethod) ApplyClass(c *rule.Context, class *model.Class) {
	for _, m := range class.Methods {
		if m.Exported {
			continue
		}
		// A method that satisfies an interface declared in the same package is
		// used even when never selected by name (the sealed-interface idiom).
		// Only a matching signature can satisfy anything: a same-named
		// interface method with an incompatible signature leaves the concrete
		// method unused.
		if !c.File.MemberSelectedForType(class.Name, m.Name) && !c.File.InterfaceMethodSatisfied(m) {
			c.ReportFunc(m, m.Name)
		}
	}
}

// ----- UnusedFormalParameter ----------------------------------------------

type UnusedFormalParameter struct{ *rule.Base }

func (r *UnusedFormalParameter) check(c *rule.Context, fn *model.Function) {
	if fn.Body == nil {
		return
	}
	for _, p := range fn.Params {
		if p.Name == "" || p.Name == "_" {
			continue
		}
		if !model.IdentifierRead(fn, p.Ident) {
			c.Report(p.Line, p.Line, p.Name)
		}
	}
}
func (r *UnusedFormalParameter) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

// ----- UnusedLocalVariable ------------------------------------------------

type UnusedLocalVariable struct {
	*rule.Base
	exceptions []string
}

func newUnusedLocalVariable() rule.Rule {
	return &UnusedLocalVariable{Base: rule.NewBase("exceptions", "allow-unused-foreach-variables")}
}

func (r *UnusedLocalVariable) Configure(props rule.Properties) error {
	r.exceptions = util.SplitToList(props.String("exceptions", ""))
	return nil
}

func (r *UnusedLocalVariable) check(c *rule.Context, fn *model.Function) {
	locals := model.LocalVariables(fn)
	reported := map[string]bool{}
	for _, v := range locals {
		if model.IdentifierRead(fn, v.Ident) || reported[v.Name] || util.Contains(r.exceptions, v.Name) {
			continue
		}
		reported[v.Name] = true
		c.Report(v.Line, v.Line, v.Name)
	}
}
func (r *UnusedLocalVariable) ApplyFunc(c *rule.Context, fn *model.Function) { r.check(c, fn) }

sources.internal/ruleset/refs.go:
package ruleset

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/quality-gates/messgo/internal/rule"
)

var leafBuiltinRulesets = []string{
	"cleancode", "codesize", "controversial", "design", "naming", "opinionated", "unusedcode",
}

type refExpander struct {
	session    *loadSession
	set        *rule.RuleSet
	candidates []ruleCandidate
	active     []string
	activePos  map[string]int
	expanded   map[string]bool
}

func newRefExpander(session *loadSession, set *rule.RuleSet) *refExpander {
	return &refExpander{
		session:   session,
		set:       set,
		activePos: make(map[string]int),
		expanded:  make(map[string]bool),
	}
}

func (e *refExpander) enter(key string) error {
	if pos, active := e.activePos[key]; active {
		cycle := append(append([]string{}, e.active[pos:]...), key)
		return fmt.Errorf("cyclic ruleset reference: %s", strings.Join(cycle, " -> "))
	}
	e.activePos[key] = len(e.active)
	e.active = append(e.active, key)
	return nil
}

func (e *refExpander) leave() {
	last := len(e.active) - 1
	delete(e.activePos, e.active[last])
	e.active = e.active[:last]
}

// addRule handles one <rule> element: either a direct class-based definition
// or a <rule ref="..."> reference to another ruleset (optionally with
// <exclude> children or single-rule property overrides).
func addRule(e *refExpander, setName string, xr xmlRule, fromDir string) error {
	switch {
	case xr.Ref != "":
		return e.addRef(xr, fromDir)
	case xr.Class != "":
		r, err := e.buildRule(setName, xr, &xr)
		if err != nil {
			return err
		}
		if r != nil {
			e.appendRuleWithKind(r, candidateDefinition, xr.Class)
		}
	}
	return nil
}

func (e *refExpander) addRef(xr xmlRule, fromDir string) error {
	_, ruleName := e.session.resolveRef(xr.Ref, fromDir)
	kind := candidateInherited
	if ruleName != "" && hasRuleOverrides(xr) {
		kind = candidateOverride
	}
	found, err := e.expandRef(xr, "", excludeSet(xr.Exclude), &xr, fromDir, kind)
	if err != nil {
		return err
	}
	if ruleName != "" && !found {
		return fmt.Errorf("unknown rule %q", xr.Ref)
	}
	return nil
}

func (e *refExpander) expandRef(xr xmlRule, wantName string, parentExclude map[string]bool, ov *xmlRule, fromDir string, kind candidateKind) (bool, error) {
	base, ruleName := e.session.resolveRef(xr.Ref, fromDir)
	if skipFilteredRef(ruleName, wantName) {
		return false, nil
	}
	ruleName = coalesceRuleName(ruleName, wantName)
	src, key, err := readSource(e.session, base, fromDir)
	if err != nil {
		return false, err
	}
	if err := e.enter(key); err != nil {
		return false, err
	}
	defer e.leave()
	excluded := mergeExclude(parentExclude, xr.Exclude)
	expansion := expansionKey(key, ruleName, excluded, ov)
	if found, alreadyExpanded := e.expanded[expansion]; alreadyExpanded {
		return found, nil
	}
	found, err := e.importSourceRules(src, ruleName, excluded, ov, rulesetDir(key), kind)
	if err != nil {
		return false, err
	}
	e.expanded[expansion] = found
	return found, nil
}

func readSource(session *loadSession, part, fromDir string) (xmlRuleSet, string, error) {
	data, loc, err := readRuleset(part, fromDir)
	if err != nil {
		return xmlRuleSet{}, "", err
	}
	return session.decode(data, loc)
}

func expansionKey(location, ruleName string, excluded map[string]bool, ov *xmlRule) string {
	var key strings.Builder
	fmt.Fprintf(&key, "%q|%q", location, ruleName)
	names := make([]string, 0, len(excluded))
	for name, isExcluded := range excluded {
		if isExcluded {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	for _, name := range names {
		fmt.Fprintf(&key, "|exclude:%q", name)
	}
	if ruleName == "" || ov == nil {
		return key.String()
	}
	if ov.Priority != nil {
		fmt.Fprintf(&key, "|priority:%d", *ov.Priority)
	}
	props := mergeProps(xmlProperties{}, ov.Properties)
	names = names[:0]
	for name := range props {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		fmt.Fprintf(&key, "|property:%q=%q", name, props[name])
	}
	return key.String()
}

func skipFilteredRef(resolved, want string) bool {
	return want != "" && resolved != "" && resolved != want
}

func hasRuleOverrides(xr xmlRule) bool {
	return xr.Priority != nil || len(xr.Properties.Property) > 0 || len(xr.Exclude) > 0
}

func coalesceRuleName(resolved, want string) string {
	if resolved != "" {
		return resolved
	}
	return want
}

func (e *refExpander) importSourceRules(src xmlRuleSet, ruleName string, excluded map[string]bool, ov *xmlRule, fromDir string, kind candidateKind) (bool, error) {
	var anyFound bool
	for _, sr := range src.Rules {
		found, err := e.expandSourceRule(src.Name, sr, ruleName, excluded, ov, fromDir, kind)
		if err != nil {
			return false, err
		}
		if found {
			anyFound = true
		}
	}
	return anyFound, nil
}

func (e *refExpander) expandSourceRule(srcName string, sr xmlRule, ruleName string, excluded map[string]bool, ov *xmlRule, fromDir string, kind candidateKind) (bool, error) {
	if sr.Ref != "" {
		return e.expandRef(sr, ruleName, excluded, refOverride(sr, ov, ruleName), fromDir, kind)
	}
	if sr.Class == "" || excluded[sr.Name] || (ruleName != "" && sr.Name != ruleName) {
		return false, nil
	}
	r, err := e.buildRule(srcName, sr, refOverride(sr, ov, ruleName))
	if err != nil {
		return false, err
	}
	if r != nil {
		e.appendRuleWithKind(r, kind, sr.Class)
	}
	return true, nil
}

func refOverride(sr xmlRule, ov *xmlRule, ruleName string) *xmlRule {
	if ruleName != "" && ov != nil {
		return ov
	}
	return &sr
}

func mergeExclude(parent map[string]bool, extra []xmlExclude) map[string]bool {
	out := map[string]bool{}
	for k, v := range parent {
		if v {
			out[k] = true
		}
	}
	for _, e := range extra {
		out[e.Name] = true
	}
	return out
}

func (s *loadSession) resolveRef(ref, fromDir string) (base, ruleName string) {
	if resolvable(ref, fromDir) {
		return ref, ""
	}
	if i := strings.LastIndex(ref, "/"); i >= 0 {
		if left := ref[:i]; resolvable(left, fromDir) {
			return left, ref[i+1:]
		}
	}
	if owner := builtinRuleOwner(s, ref); owner != "" {
		return owner, ref
	}
	return ref, ""
}

func resolvable(ident, fromDir string) bool {
	if _, ok := builtinNames[ident]; ok {
		return true
	}
	_, err := os.Stat(resolvePath(ident, fromDir))
	return err == nil
}

func resolvePath(part, fromDir string) string {
	if fromDir != "" && !filepath.IsAbs(part) {
		return filepath.Join(fromDir, part)
	}
	return part
}

// buildRule constructs a configured rule from a definition (def, which carries
// message/class/url/since/description) and an override source (ov, which
// carries priority and property overrides — usually the same element, but for
// a single-rule ref it is the referencing element).
func (e *refExpander) buildRule(setName string, def xmlRule, ov *xmlRule) (rule.Rule, error) {
	ctor, ok := rule.Lookup(def.Class)
	if !ok {
		warnSkipped(e, "skipping unimplemented rule %s (%s)", def.Name, def.Class)
		return nil, nil
	}
	r := ctor()
	base := rule.BaseOf(r)
	if base == nil {
		warnSkipped(e, "rule %s does not expose metadata", def.Name)
		return nil, nil
	}
	base.RuleName = def.Name
	base.RuleMessage = strings.TrimSpace(def.Message)
	base.RuleSet = setName
	base.RuleURL = def.ExternalInfoURL
	base.RuleSince = def.Since
	base.RuleDesc = strings.TrimSpace(def.Description)
	base.RulePrio = 3
	if def.Priority != nil {
		base.RulePrio = *def.Priority
	}
	base.RuleProps = mergeProps(def.Properties, ov.Properties)
	warnUnknownProperties(e, def, ov, r)
	if ov.Priority != nil {
		base.RulePrio = *ov.Priority
	}
	if configurable, configurableRule := r.(rule.Configurable); configurableRule {
		if err := configurable.Configure(base.RuleProps); err != nil {
			return nil, fmt.Errorf("configure rule %s: %w", def.Name, err)
		}
	}
	return r, nil
}

// appendRuleWithKind adds a rule unless it is filtered out by the configured
// priority bounds, retaining the candidate's merge provenance.
func (e *refExpander) appendRuleWithKind(r rule.Rule, kind candidateKind, class string) {
	priority := rule.BaseOf(r).RulePrio
	loader := e.session.loader
	if loader.MinPriority > 0 && priority > loader.MinPriority {
		return
	}
	if loader.MaxPriority > 0 && priority < loader.MaxPriority {
		return
	}
	e.set.Rules = append(e.set.Rules, r)
	e.candidates = append(e.candidates, ruleCandidate{rule: r, class: class, kind: kind})
}

func (e *refExpander) warn(format string, args ...any) {
	if e.session.loader.Warn != nil {
		e.session.loader.Warn(fmt.Sprintf(format, args...))
	}
}

func warnSkipped(e *refExpander, format string, args ...any) {
	if e.session.loader.Verbose {
		e.warn(format, args...)
	}
}

func warnUnknownProperties(e *refExpander, def xmlRule, ov *xmlRule, r rule.Rule) {
	known := declaredPropertyNames(r)
	for _, name := range unknownPropertyNames(known, ov.Properties) {
		e.warn("rule %s has no property %q; ignored", def.Name, name)
	}
}

type propertyNameLister interface {
	PropertyNames() []string
}

func declaredPropertyNames(r rule.Rule) map[string]bool {
	set := map[string]bool{}
	if base := rule.BaseOf(r); base != nil {
		addNames(set, base.KnownProps)
	}
	if lister, ok := r.(propertyNameLister); ok {
		addNames(set, lister.PropertyNames())
	}
	return set
}

func addNames(set map[string]bool, names []string) {
	for _, name := range names {
		if name != "" {
			set[name] = true
		}
	}
}

func unknownPropertyNames(known map[string]bool, props xmlProperties) []string {
	var unknown []string
	seen := map[string]bool{}
	for _, p := range props.Property {
		if p.Name == "" || !hasPropValue(p) || known[p.Name] || seen[p.Name] {
			continue
		}
		seen[p.Name] = true
		unknown = append(unknown, p.Name)
	}
	sort.Strings(unknown)
	return unknown
}

