package util

import (
	"go/ast"
	"go/token"
)

// LocalVar is a variable declared inside a function body.
type LocalVar struct {
	Name   string
	Ident  *ast.Ident
	Line   int
	IsLoop bool // declared as a for-init or range loop variable
}

// LocalVariables collects the variables declared within a function body:
// short variable declarations (:=), `var` declarations, for-loop counters and
// range variables. The blank identifier is skipped. This is the Go analog of
// pdepend's VariableDeclarator nodes.
func LocalVariables(body *ast.BlockStmt, fset *token.FileSet) []LocalVar {
	lc := &localCollector{
		fset: fset,
		loop: collectLoopIdents(body),
		seen: map[*ast.Ident]bool{},
	}
	ast.Inspect(body, lc.collect)
	return lc.out
}

type localCollector struct {
	fset *token.FileSet
	loop map[*ast.Ident]bool
	seen map[*ast.Ident]bool
	out  []LocalVar
}

func (lc *localCollector) add(id *ast.Ident) {
	if id == nil || id.Name == "_" || lc.seen[id] {
		return
	}
	lc.seen[id] = true
	lc.out = append(lc.out, LocalVar{
		Name:   id.Name,
		Ident:  id,
		Line:   lc.fset.Position(id.Pos()).Line,
		IsLoop: lc.loop[id],
	})
}

func (lc *localCollector) collect(node ast.Node) bool {
	switch s := node.(type) {
	case *ast.FuncLit:
		return false
	case *ast.AssignStmt:
		for _, id := range defineIdents(s) {
			lc.add(id)
		}
	case *ast.DeclStmt:
		for _, id := range varDeclIdents(s) {
			lc.add(id)
		}
	case *ast.RangeStmt:
		if s.Tok == token.DEFINE {
			lc.add(identOf(s.Key))
			lc.add(identOf(s.Value))
		}
	}
	return true
}

// collectLoopIdents returns the set of identifiers declared as for-loop
// counters (the := init of a ForStmt), which callers may treat specially.
func collectLoopIdents(body *ast.BlockStmt) map[*ast.Ident]bool {
	set := map[*ast.Ident]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		switch fs := n.(type) {
		case *ast.FuncLit:
			return false
		case *ast.ForStmt:
			if a, ok := fs.Init.(*ast.AssignStmt); ok {
				for _, id := range defineIdents(a) {
					set[id] = true
				}
			}
		case *ast.RangeStmt:
			if fs.Tok == token.DEFINE {
				addLoopIdent(set, fs.Key)
				addLoopIdent(set, fs.Value)
			}
		}
		return true
	})
	return set
}

// addLoopIdent adds e's identifier to set if e is an identifier.
func addLoopIdent(set map[*ast.Ident]bool, e ast.Expr) {
	if id := identOf(e); id != nil {
		set[id] = true
	}
}

// DeclaredBy reports whether id's resolved object is declared by decl.
func DeclaredBy(id *ast.Ident, decl ast.Node) bool {
	return id != nil && id.Obj != nil && id.Obj.Decl == decl
}

// defineIdents returns the LHS identifiers newly declared by a `:=` assignment.
func defineIdents(a *ast.AssignStmt) []*ast.Ident {
	if a.Tok != token.DEFINE {
		return nil
	}
	var ids []*ast.Ident
	for _, lhs := range a.Lhs {
		id := identOf(lhs)
		if DeclaredBy(id, a) {
			ids = append(ids, id)
		}
	}
	return ids
}

// varDeclIdents returns the names declared by a `var` declaration statement.
func varDeclIdents(s *ast.DeclStmt) []*ast.Ident {
	gd, ok := s.Decl.(*ast.GenDecl)
	if !ok || gd.Tok != token.VAR {
		return nil
	}
	var ids []*ast.Ident
	for _, spec := range gd.Specs {
		if vs, ok := spec.(*ast.ValueSpec); ok {
			ids = append(ids, vs.Names...)
		}
	}
	return ids
}

func identOf(e ast.Expr) *ast.Ident {
	id, _ := e.(*ast.Ident)
	return id
}

// MutatedGlobalNames returns the set of package-level variable names that are
// mutated somewhere across the given files (the files of a single package).
// A variable is "mutated" if it is reassigned (`=`, `+=`, ...), incremented or
// decremented, has a field/element written through it (`g.f = x`, `g[k] = v`),
// or has its address taken (`&g`). Short variable declarations (`:=`) introduce
// locals and are ignored, as are the variables' own initializers (which are
// declarations, not assignments). The result is intersected with the names
// actually declared as package-level vars, so locals never appear.
//
// Detection is AST-based and deliberately errs toward visibility: a local that
// shadows a global name (via `var`) may cause the global to be reported, which
// is preferable to hiding a genuinely mutable global.
func MutatedGlobalNames(files []*ast.File) map[string]bool {
	globals, topSpecs := topLevelVarNames(files)
	mutated := map[string]bool{}
	if len(globals) == 0 {
		return mutated
	}
	for _, f := range files {
		collectMutations(f, globals, topSpecs, mutated)
	}
	return mutated
}

// collectMutations records, into mutated, every name in globals that is mutated
// anywhere in f.
func collectMutations(f *ast.File, globals map[string]bool, topSpecs map[any]bool, mutated map[string]bool) {
	mark := func(e ast.Expr) {
		id := rootIdent(e)
		if id == nil || !globals[id.Name] {
			return
		}
		if id.Obj != nil && !topSpecs[id.Obj.Decl] {
			return
		}
		mutated[id.Name] = true
	}
	ast.Inspect(f, func(n ast.Node) bool {
		markMutation(n, mark)
		return true
	})
}

// markMutation calls mark on the lvalue(s) of any node that mutates a variable:
// assignment (excluding ":=", which introduces locals), increment/decrement,
// address-of, delete/clear of a map, and a range clause that assigns into
// existing variables.
func markMutation(n ast.Node, mark func(ast.Expr)) {
	switch s := n.(type) {
	case *ast.AssignStmt:
		if s.Tok == token.DEFINE {
			return
		}
		for _, lhs := range s.Lhs {
			mark(lhs)
		}
	case *ast.IncDecStmt:
		mark(s.X)
	case *ast.UnaryExpr:
		if s.Op == token.AND {
			mark(s.X)
		}
	case *ast.RangeStmt:
		markRangeAssign(s, mark)
	case *ast.CallExpr:
		markDeleteOrClear(s, mark)
	}
}

func markRangeAssign(s *ast.RangeStmt, mark func(ast.Expr)) {
	if s.Tok != token.ASSIGN {
		return
	}
	mark(s.Key)
	mark(s.Value)
}

func markDeleteOrClear(call *ast.CallExpr, mark func(ast.Expr)) {
	id, ok := call.Fun.(*ast.Ident)
	if !ok || (id.Name != "delete" && id.Name != "clear") {
		return
	}
	if len(call.Args) == 0 {
		return
	}
	mark(call.Args[0])
}

// topLevelVarNames collects the names declared in package-level `var`
// declarations across the files and the set of top-level ValueSpec nodes.
// The blank identifier is skipped.
func topLevelVarNames(files []*ast.File) (map[string]bool, map[any]bool) {
	names := map[string]bool{}
	specs := map[any]bool{}
	for _, f := range files {
		for _, decl := range f.Decls {
			collectGenDeclVars(decl, names, specs)
		}
	}
	return names, specs
}

func collectGenDeclVars(decl ast.Decl, names map[string]bool, specs map[any]bool) {
	gd, ok := decl.(*ast.GenDecl)
	if !ok || gd.Tok != token.VAR {
		return
	}
	for _, spec := range gd.Specs {
		collectValueSpecVars(spec, names, specs)
	}
}

func collectValueSpecVars(spec ast.Spec, names map[string]bool, specs map[any]bool) {
	vs, ok := spec.(*ast.ValueSpec)
	if !ok {
		return
	}
	specs[vs] = true
	for _, name := range vs.Names {
		if name.Name != "_" {
			names[name.Name] = true
		}
	}
}

// rootIdent peels selector, index, star and paren wrappers off an lvalue to its
// leading identifier: x, x.f, x[i], *x, (x) all reduce to x. Returns nil if the
// expression is not rooted at an identifier.
func rootIdent(e ast.Expr) *ast.Ident {
	for {
		switch t := e.(type) {
		case *ast.Ident:
			return t
		case *ast.SelectorExpr:
			e = t.X
		case *ast.IndexExpr:
			e = t.X
		case *ast.IndexListExpr:
			e = t.X
		case *ast.StarExpr:
			e = t.X
		case *ast.ParenExpr:
			e = t.X
		default:
			return nil
		}
	}
}

// FindCalls returns all call expressions in a node whose callee renders to one
// of the given function names (matched against the textual call expression,
// e.g. "fmt.Println" or "panic").
type Call struct {
	Expr *ast.CallExpr
	Name string // dotted name of the callee
	Line int
}

// Calls returns every call expression within n along with its dotted callee
// name and line.
func Calls(n ast.Node, fset *token.FileSet) []Call {
	var out []Call
	ast.Inspect(n, func(node ast.Node) bool {
		if ce, ok := node.(*ast.CallExpr); ok {
			out = append(out, Call{Expr: ce, Name: CalleeName(ce.Fun), Line: fset.Position(ce.Pos()).Line})
		}
		return true
	})
	return out
}

// CalleeName renders a call's function expression to a dotted name, e.g.
// "fmt.Println", "os.Exit", "panic". Returns "" if it can't be expressed.
func CalleeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		if x := CalleeName(t.X); x != "" {
			return x + "." + t.Sel.Name
		}
		return t.Sel.Name
	case *ast.ParenExpr:
		return CalleeName(t.X)
	}
	return ""
}

// TypeAliasNames maps each type-alias name declared across the given files
// (`type alias = original`) to the local type name it aliases. Aliases of
// types from other packages, and of unnamed types such as struct literals,
// are omitted: there is no local named type for them to denote.
func TypeAliasNames(files []*ast.File) map[string]string {
	aliases := map[string]string{}
	for _, f := range files {
		for _, decl := range f.Decls {
			if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
				collectTypeAliases(gen, aliases)
			}
		}
	}
	return aliases
}

func collectTypeAliases(gen *ast.GenDecl, aliases map[string]string) {
	for _, spec := range gen.Specs {
		ts, ok := spec.(*ast.TypeSpec)
		if !ok || !ts.Assign.IsValid() {
			continue
		}
		if target := aliasTargetName(ts.Type); target != "" && target != ts.Name.Name {
			aliases[ts.Name.Name] = target
		}
	}
}

// aliasTargetName unwraps pointers and generic instantiations to the bare
// identifier naming an alias target.
func aliasTargetName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return aliasTargetName(t.X)
	case *ast.ParenExpr:
		return aliasTargetName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr:
		return aliasTargetName(t.X)
	case *ast.IndexListExpr:
		return aliasTargetName(t.X)
	}
	return ""
}

// ResolveTypeAlias follows a chain of type aliases to the name of the defined
// type they denote. Names that are not aliases are returned unchanged, and a
// cyclic chain resolves to the name it started from.
func ResolveTypeAlias(aliases map[string]string, name string) string {
	seen := map[string]bool{}
	for {
		target, ok := aliases[name]
		if !ok || seen[name] {
			return name
		}
		seen[name] = true
		name = target
	}
}

